// ---------- Matchstick patterns ----------
gen('m_matchsticks', MC, 'Matchstick patterns', { F: [1, 2], H: [2], calc: 'nocalc', spec: 'A23, A24, A22' }, (r, band) => {
  const [shape, k] = r.pick([['triangle', 2], ['square', 3], ['pentagon', 4], ['hexagon', 5]]), n = v('n');
  const f = (i) => k * i + 1, rows = [['Pattern number', 1, 2, 3], ['Number of matches', f(1), f(2), f(3)]];
  const nn = `${k}${n} + 1`;
  const fx = (x) => isInt(x * 100) ? N(clean(x)) : N(x, 2) + ' (to 2 d.p.)'; // never print a long recurring decimal
  const parts = [];
  if (band === 1) parts.push({ lab: '(a)', q: 'Write down the number of matches in Pattern 4.', marks: 1, ans: String(f(4)), ms: [B('cao')], space: 1 });
  parts.push({ lab: band === 1 ? '(b)' : '(a)', q: `Write an expression, in terms of ${n}, for the number of matches in Pattern ${n}.`, marks: 2, ans: nn, ms: [M(`for a linear expression with ${k}${n}`), A(`for ${nn}`)], line: { pre: 'Number of matches = ' }, space: 1.5 });
  const valid = r.chance(0.5), n0 = r.int(10, 40), Nt = valid ? f(n0) : f(n0) + r.int(1, k - 1);
  parts.push({ lab: band === 1 ? '(c)' : '(b)', q: `Ali says, "There is a pattern that uses exactly ${Nt} matches."<br>Is Ali correct? You must show how you decide.`, marks: 2,
    ans: valid ? `Yes. ${k}${n} + 1 = ${Nt} gives ${n} = ${n0}, a whole number.` : `No. ${k}${n} + 1 = ${Nt} gives ${n} = ${fx((Nt - 1) / k)}, which is not a whole number.`,
    ms: [M(`for ${k}${n} + 1 = ${Nt} or (${Nt} ${MINUS} 1) ÷ ${k} (ft their expression)`), A(valid ? `for ${n0} and 'yes' (a whole number)` : `for ${fx((Nt - 1) / k)} and 'no' (not a whole number)`)], line: null, space: 2 });
  if (band >= 2) {
    const M_ = r.int(100, 300), nmax = Math.floor((M_ - 1) / k);
    parts.push({ lab: '(c)', q: `Sam has ${M_} matches. What is the largest pattern number Sam can make?`, marks: 2, ans: `Pattern ${nmax}`, ms: [M(`for ${k}${n} + 1 ≤ ${M_} or (${M_} ${MINUS} 1) ÷ ${k} (= ${fx((M_ - 1) / k)}) (ft)`), A(`for ${nmax}`)], line: { pre: 'Pattern ' }, space: 2 });
  }
  return { stem: `Here are the numbers of matches needed to make a row of ${shape}s. Pattern ${n} is a row of ${n} ${shape}s.`, fig: htable(rows), parts };
});

// ---------- Linear equations in context ----------
gen('m_linear_context', MC, 'Taxi fares and equations', { F: [1, 2], H: [2, 3], calc: 'nocalc', spec: 'A17, A21, A9' }, (r, band) => {
  const d = v('d');
  for (let t = 0; t < 600; t++) {
    const f = r.int(2, 6), m = r.pick([1, 1.5, 2, 2.5, 3]), D1 = r.int(4, 12), D2 = r.int(5, 15);
    const C = f + m * D2, c1 = f + m * D1, nm = r.pick(NAMES);
    const parts = [
      { lab: '(a)', q: `Work out the cost of ${aan(D1)} ${D1}-mile journey with Firm <b>A</b>.`, marks: 2, ans: money(c1), ms: [M(`for ${money(f)} + ${D1} × ${money(m)} oe`), A(`for ${N(c1)}`)], line: { pre: '£' }, space: 1.5 },
      { lab: '(b)', q: `${nm}'s journey with Firm <b>A</b> costs ${money(C)}. Work out how many miles ${pron(nm)} travelled.`, marks: 3, ans: `${D2} miles`, ms: [M(`for ${N(C)} ${MINUS} ${N(f)} (= ${N(C - f)})`), M(`for ${N(C - f)} ÷ ${N(m)}`), A(`for ${D2}`)], line: { post: 'miles' }, space: 2.5 }];
    if (band >= 2) {
      const dl = r.pick([0.5, 1]), n = m - dl;
      if (n <= 0) continue;
      const ds = r.int(4, 10), g = f + dl * ds;
      if (band === 2) {
        const D3 = r.int(3, 14), cA = f + m * D3, cB = g + n * D3;
        if (cA === cB) continue;
        parts.push({ lab: '(c)', q: `Firm <b>B</b> charges a fixed charge of ${money(g)} plus ${money(n)} for each mile.<br>${cap(nm)} needs ${aan(D3)} ${D3}-mile journey. Which firm is cheaper, and by how much? You must show your working.`, marks: 3, ans: `Firm ${cA < cB ? 'A' : 'B'} is cheaper, by ${money(Math.abs(cA - cB))}`, ms: [M(`for ${N(g)} + ${D3} × ${N(n)} (= ${N(cB)}) or ${N(f)} + ${D3} × ${N(m)} (= ${N(cA)})`), M('for both costs found and compared'), A(`for Firm ${cA < cB ? 'A' : 'B'} and ${N(Math.abs(cA - cB))}`)], line: null, space: 3 });
      } else {
        parts.push({ lab: '(c)', q: `Firm <b>B</b> charges a fixed charge of ${money(g)} plus ${money(n)} for each mile.<br>For one particular journey, both firms charge the same amount. By forming and solving an equation, work out the length of this journey.`, marks: 4, ans: `${ds} miles`, ms: [M(`for ${N(f)} + ${N(m)}${d} = ${N(g)} + ${N(n)}${d} oe`), M(`for collecting terms: ${term(clean(m - n), d, true)} = ${N(g - f)} oe`), M(`for ${N(g - f)} ÷ ${N(dl)}`), A(`for ${ds}`)], line: { post: 'miles' }, space: 3.5 });
        parts.push({ lab: '(d)', q: 'Which firm is cheaper for journeys longer than this? Give a reason for your answer.', marks: 1, ans: `Firm B, because it charges less per mile (${money(n)} compared with ${money(m)})`, ms: [B('for Firm B with a reason, e.g. a smaller cost per mile')], line: null, space: 1.2 });
      }
    }
    return { stem: `Taxi Firm <b>A</b> charges a fixed charge of ${money(f)} plus ${money(m)} for each mile.`, parts };
  }
  return null;
});

// ---------- Two-way tables + probability + percentages ----------
gen('m_two_way', MC, 'Two-way tables, probability and percentages', { F: [1, 2], H: [2], calc: 'nocalc', spec: 'S1, P4, R9' }, (r, band) => {
  for (let t = 0; t < 800; t++) {
    const T1 = r.pick([40, 50, 60, 80]), T2 = r.pick([30, 40, 50, 60]);
    const row = (T) => { const w = r.int(4, Math.floor(T / 2)), b = r.int(4, Math.floor(T / 2)), c = T - w - b; return [w, b, c]; };
    const y10 = row(T1), y11 = row(T2);
    if (y10[2] < 3 || y11[2] < 3 || (y10[1] * 100) % T1 !== 0) continue;
    const tot = [y10[0] + y11[0], y10[1] + y11[1], y10[2] + y11[2]], all = T1 + T2;
    const shown = (v_, hide) => hide ? '' : v_;
    const rows = [['', 'Walk', 'Bus', 'Car', 'Total'],
      ['Year 10', shown(y10[0], true), y10[1], shown(y10[2], true), T1],
      ['Year 11', y11[0], shown(y11[1], true), y11[2], T2],
      ['Total', tot[0], tot[1], tot[2], all]];
    const parts = [
      { lab: '(a)', q: 'Complete the two-way table.', marks: 2, ans: `Year 10: Walk ${y10[0]}, Car ${y10[2]}; Year 11: Bus ${y11[1]}`, ms: [B('for at least one missing value correct'), B('for all three missing values correct')], line: null, space: 0.3 },
      { lab: '(b)', q: 'One of the students is picked at random. Work out the probability that this student walks to school.', marks: 2, ans: new Frac(tot[0], all).html(), ms: [M(`for ${tot[0]} out of ${all} (ft their table)`), A(`for ${fr(tot[0], all)} oe`)], line: null, space: 1.5 },
      { lab: '(c)', q: 'One of the Year 11 students is picked at random. Work out the probability that this student comes by car.', marks: 2, ans: new Frac(y11[2], T2).html(), ms: [M(`for ${y11[2]} out of ${T2} (ft)`), A(`for ${fr(y11[2], T2)} oe`)], line: null, space: 1.5 }];
    if (band >= 2) parts.push({ lab: '(d)', q: 'What percentage of the Year 10 students come by bus?', marks: 2, ans: `${y10[1] * 100 / T1}%`, ms: [M(`for ${y10[1]} ÷ ${T1} × 100 or ${fr(y10[1], T1)} as a percentage`), A(`for ${y10[1] * 100 / T1}`)], line: { post: '%' }, space: 1.5 });
    return { stem: 'The two-way table shows information about how some students in Year 10 and Year 11 travel to school.', fig: table(rows, { rowHead: true }), parts };
  }
  return null;
});

// ---------- Volume, density and cost ----------
gen('m_density', MC, 'Volume, density and cost', { F: [2], H: [2, 3], calc: 'calc', spec: 'R11, G16, G17' }, (r, band) => {
  const [metal, rho, price] = r.pick([['aluminium', 2.7, 1.2], ['iron', 7.8, 0.4], ['copper', 8.9, 6.5], ['lead', 11.3, 1.4], ['brass', 8.5, 3.2]]);
  for (let t = 0; t < 600; t++) {
    if (band < 3) {
      const l = r.int(8, 30), w = r.int(5, 20), h = r.int(4, 15), V = l * w * h, gm = V * rho;
      if (Math.abs(gm - Math.round(gm)) > 1e-6) continue;
      const kg = gm / 1000, cost = roundDp(kg * price, 2);
      if (kg > 25) continue;
      return { stem: `The diagram shows a solid block of ${metal} in the shape of a cuboid.<br>The density of ${metal} is ${N(rho)} g/cm${sup(3)}.`, fig: cuboidFig(l, w, h, [`${l} cm`, `${w} cm`, `${h} cm`]), nad: true, parts: [
        { lab: '(a)', q: 'Work out the volume of the block.', marks: 2, ans: `${N(V)} cm${sup(3)}`, ms: [M(`for ${l} × ${w} × ${h}`), A(`for ${V}`)], line: { post: 'cm³' }, space: 1.5 },
        { lab: '(b)', q: 'Work out the mass of the block. Give your answer in kilograms.', marks: 3, ans: `${N(kg)} kg`, ms: [M(`for ${N(rho)} × ${V} (= ${N(clean(gm))} g) (ft)`), M('for ÷ 1000 to convert grams to kilograms'), A(`for ${N(kg)}`)], line: { post: 'kg' }, space: 2.5 },
        { lab: '(c)', q: `Scrap ${metal} is bought for £${N(price, 2)} per kilogram. Work out how much the block is worth as scrap. Give your answer to the nearest penny.`, marks: 2, ans: money(cost, true), ms: [M(`for ${N(kg)} × ${N(price, 2)} (ft)`), A(`for ${N(cost, 2)}`)], line: { pre: '£' }, space: 1.5 }] };
    } else {
      const rr = r.int(2, 8), h = r.int(5, 20), V = Math.PI * rr * rr * h, V3 = roundSf(V, 3), kg = V * rho / 1000, kg3 = SF(kg, 3), kgFromRounded = SF(V3 * rho / 1000, 3);
      if (kg3 !== kgFromRounded) continue;
      return { stem: `The diagram shows a solid cylinder made of ${metal}.<br>The density of ${metal} is ${N(rho)} g/cm${sup(3)}.`, fig: cylinderFig(`${rr} cm`, `${h} cm`), nad: true, parts: [
        { lab: '(a)', q: 'Work out the volume of the cylinder. Give your answer correct to 3 significant figures.', marks: 2, ans: `${SF(V, 3)} cm${sup(3)}`, ms: [M(`for π × ${rr}${sup(2)} × ${h}`), A(`for ${SF(V, 3)} (awrt)`)], line: { post: 'cm³' }, space: 1.5 },
        { lab: '(b)', q: 'Work out the mass of the cylinder. Give your answer in kilograms, correct to 3 significant figures.', marks: 3, ans: `${kg3} kg`, ms: [M(`for ${N(rho)} × their volume (in grams)`), M('for ÷ 1000 to convert grams to kilograms'), A(`for ${kg3} (awrt)`)], line: { post: 'kg' }, space: 2.5 }] };
    }
  }
  return null;
});

// ---------- Age problems ----------
gen('m_age', MC, 'Age problems', { F: [1, 2], H: [2, 3], calc: 'nocalc', spec: 'A17, R5' }, (r, band) => {
  const X = v('x'), [n1, n2] = r.sample(NAMES, 2);
  if (band < 3) {
    for (let t = 0; t < 300; t++) {
      const c = band === 1 ? 3 : r.pick([3, 4]), x = r.int(8, 13), a = r.int(2, 6);
      if (c * x > 52 || c * x < 24 || (c - 1) * x < 20) continue; // mother at least 20 years older than the child
      const T = (c + 2) * x + a, tot = lin(c + 2, a);
      return { stem: `${n1} is ${X} years old.<br>${n2}, ${poss(n1)} ${SHE.has(n2) ? 'sister' : 'brother'}, is ${a} years older than ${n1}.<br>${n1}'s mother is ${c === 2 ? 'twice' : c + ' times'} as old as ${n1}.<br>The sum of the ages of ${n1}, ${n2} and ${n1}'s mother is ${T}.`, parts: [
        { lab: '(a)', q: `Write down an expression, in terms of ${X}, for the sum of their ages. Give your answer in its simplest form.`, marks: 2, ans: tot, ms: [M(`for ${X} + (${X} + ${a}) + ${c}${X}`), A(`for ${tot}`)], line: null, space: 1.2 },
        { lab: '(b)', q: `Work out the value of ${X}.`, marks: 2, ans: `${X} = ${x}`, ms: [M(`for ${tot} = ${T} or ${N(c + 2)}${X} = ${T - a}`), A(`for ${x}`)], line: { pre: X + ' = ' }, space: 1.5 },
        { lab: '(c)', q: `How old is ${n1}'s mother?`, marks: 1, ans: `${c * x} years`, ms: [B(`for ${c * x} (ft their ${X})`)], line: { post: 'years old' }, space: 0.8 }] };
    }
    return null;
  }
  for (let t = 0; t < 600; t++) {
    const a = r.int(1, 4), b = r.int(a + 1, 6);
    if (gcd(a, b) > 1) continue;
    const k = r.int(2, 9), n = r.int(2, 12), A_ = a * k, B_ = b * k, g = gcd(A_ + n, B_ + n), c = (A_ + n) / g, d = (B_ + n) / g;
    if (c > 15 || d > 15 || (c === a && d === b) || A_ < 8 || B_ > 45) continue;
    return { stem: `The ages of ${n1} and ${n2} are in the ratio ${a} : ${b}.<br>In ${n} years' time, the ratio of their ages will be ${c} : ${d}.`, parts: [
      { lab: '(a)', q: `Work out how old ${n1} and ${n2} are now.`, marks: 4, ans: `${n1} is ${A_} and ${n2} is ${B_}`, ms: [M(`for ${a}${v('k')} + ${n} and ${b}${v('k')} + ${n} (ages in ${n} years)`), M(`for ${d}(${a}${v('k')} + ${n}) = ${c}(${b}${v('k')} + ${n}) oe`), M(`for solving to get ${v('k')} = ${k}`), A(`for ${A_} and ${B_}`)], line: null, space: 4 },
      { lab: '(b)', q: `How old will ${n2} be in ${n} years' time?`, marks: 1, ans: `${B_ + n} years`, ms: [B(`for ${B_ + n} (ft)`)], line: { post: 'years old' }, space: 0.8 }] };
  }
  return null;
});

