gen('s_averages', 'Statistics', 'Averages & range', { F: [1, 2], H: [2], calc: 'nocalc', spec: 'S4' }, (r, band, ctx) => {
  if (band === 1) {
    let d; do { d = Array.from({ length: r.pick([7, 9]) }, () => r.int(2, 19)); } while (!isInt(d.reduce((a, b) => a + b, 0) / d.length) || (() => { const c = {}; d.forEach(x => c[x] = (c[x] || 0) + 1); const m = Math.max(...Object.values(c)); return Object.values(c).filter(x => x === m).length !== 1 || m < 2; })());
    const s = d.slice().sort((a, b) => a - b), cnt = {}; d.forEach(x => cnt[x] = (cnt[x] || 0) + 1);
    const mode = +Object.keys(cnt).sort((a, b) => cnt[b] - cnt[a])[0];
    const mean0 = d.reduce((a, b) => a + b, 0) / d.length, med0 = s[(s.length - 1) / 2];
    if (new Set([mode, med0, mean0]).size < 3) return null; // the three averages should differ
    const ctxt = r.pick(['numbers of points scored by a basketball player in some games', 'numbers of text messages sent by some students on one day', 'numbers of books read by some students in one term']);
    return { stem: `Here are the ${ctxt}.<div class="numlist">${d.join('&emsp;')}</div>`, parts: [
      { lab: '(a)', q: 'Write down the mode.', marks: 1, ans: String(mode), ms: [B('cao')], space: 0.5 },
      { lab: '(b)', q: 'Work out the range.', marks: 1, ans: String(s[s.length - 1] - s[0]), ms: [B('cao')], space: 1 },
      { lab: '(c)', q: 'Find the median.', marks: 1, ans: String(s[(s.length - 1) / 2]), ms: [B('cao')], space: 1.5 },
      { lab: '(d)', q: 'Work out the mean.', marks: 2, ans: N(d.reduce((a, b) => a + b, 0) / d.length), ms: [M(`for ${d.reduce((a, b) => a + b, 0)} ÷ ${d.length}`), A()], space: 2 }] };
  }
  const n = r.int(5, 8), mean = r.int(6, 15);
  const known = Array.from({ length: n - 1 }, () => r.int(mean - 5, mean + 6));
  const last = mean * n - known.reduce((a, b) => a + b, 0);
  if (last < 1 || last > 40) return null;
  const n2 = r.int(5, 9), m1 = r.int(20, 40);
  let newP = r.int(m1 + 3, m1 + 25);
  if (ctx && ctx.calc === false) { while ((m1 * n2 + newP) % (n2 + 1) !== 0) newP++; if (newP > m1 + 25) return null; } // non-calculator: new mean must be exact
  const m2 = (m1 * n2 + newP) / (n2 + 1);
  if (!isInt(m2) && Math.abs((roundDp(m2 * 100, 6) % 10) - 5) < 1e-6) return null; // exactly half-way at 1 d.p. is ambiguous to round
  return { parts: [
    { lab: '(a)', q: `${n} numbers have a mean of ${mean}. ${n - 1} of the numbers are ${listAnd(known.map(String))}.<br>Work out the other number.`, marks: 2, ans: String(last), ms: [M(`for ${mean} × ${n} (= ${mean * n})`), A()], space: 2 },
    { lab: '(b)', q: `The mean age of ${n2} people in a group is ${m1} years. A person aged ${newP} joins the group. Work out the new mean age.${isInt(m2) ? '' : ' Give your answer correct to 1 decimal place.'}`, marks: 3, ans: `${isInt(m2) ? N(m2) : N(m2, 1)} years`, ms: [M(`for ${m1} × ${n2} (= ${m1 * n2})`), M(`for (${m1 * n2} + ${newP}) ÷ ${n2 + 1}`), A()], line: { post: 'years' }, space: 3, }] , calc: isInt(m2) ? undefined : 'either' };
});

gen('s_freq_tables', 'Statistics', 'Frequency tables & grouped data', { F: [2], H: [2, 3], calc: 'either', spec: 'S3, S4' }, (r, band, ctx) => {
  if (band === 2 && r.chance(0.5)) {
    const xs = [0, 1, 2, 3, 4];
    let fs; do { fs = xs.map(() => r.int(2, 15)); } while (!isInt(fs.reduce((s, f, i) => s + f * xs[i], 0) / fs.reduce((a, b) => a + b, 0) * 10));
    const tot = fs.reduce((a, b) => a + b, 0), sfx = fs.reduce((s, f, i) => s + f * xs[i], 0);
    const what = r.pick(['pets', 'brothers and sisters', 'goals scored']);
    const fig = table([[`Number of ${what}`, 'Frequency'], ...xs.map((x, i) => [x, fs[i]])]);
    return { stem: what === 'goals scored' ? `The table shows information about the number of goals scored by each of ${tot} players in a season.` : `The table shows information about the number of ${what} that each of ${tot} students has.`, fig, parts: [
      { lab: '(a)', q: 'Write down the mode.', marks: 1, ans: String(xs[fs.indexOf(Math.max(...fs))]), ms: [B('cao')], space: 0.5 },
      { lab: '(b)', q: 'Work out the mean.', marks: 3, ans: N(sfx / tot), ms: [M(`for at least 3 products of number × frequency`), M(`for ${sfx} ÷ ${tot}`), A()], space: 3 }].filter((p, i) => i === 1 || fs.filter(f => f === Math.max(...fs)).length === 1).map((p, i) => Object.assign(p, { lab: '(' + 'ab'[i] + ')' })) };
  }
  // grouped data
  const unit = r.pick([['Time, t (minutes)', 't'], ['Mass, m (grams)', 'm'], ['Height, h (cm)', 'h']]);
  const w = unit[1] === 'm' ? r.pick([10, 20]) : r.pick([10, 5, 20]), start = unit[1] === 'm' ? r.pick([80, 100, 120]) : r.pick([0, 10, 20]) * (w / 10);
  const k = 5;
  const bounds = Array.from({ length: k }, (_, i) => [start + i * w, start + (i + 1) * w]);
  let fs; for (let t = 0; t < 400; t++) { fs = bounds.map(() => r.int(3, 18)); const tt = fs.reduce((x, y) => x + y, 0), sm = fs.reduce((x, f, i) => x + f * (bounds[i][0] + bounds[i][1]) / 2, 0); if (ctx.calc || isInt(roundDp(sm / tt * 10, 6))) break; }
  const tot = fs.reduce((a, b) => a + b, 0);
  const mids = bounds.map(([a, b]) => (a + b) / 2);
  const sfx = fs.reduce((s, f, i) => s + f * mids[i], 0), est = sfx / tot;
  if (!ctx.calc && !isInt(roundDp(est * 10, 6))) return null; // non-calculator: the mean must come out exactly
  if (!isInt(roundDp(est * 10, 6)) && Math.abs((roundDp(est * 100, 6) % 10) - 5) < 1e-6) return null; // exactly half-way at 1 d.p. is ambiguous
  const un = { t: 'minutes', m: 'g', h: 'cm' }[unit[1]];
  const fig = table([[unit[0].replace(/, (\w) /, (m0, l) => `, <i>${l}</i> `), 'Frequency'], ...bounds.map(([a, b], i) => [`${a} < <i>${unit[1]}</i> ≤ ${b}`, fs[i]])]);
  const cum = []; fs.reduce((s, f, i) => { cum[i] = s + f; return s + f; }, 0);
  if (cum.some(c => c === tot / 2)) return null; // median would fall on a class boundary
  const medClass = bounds[cum.findIndex(c => c >= (tot + 1) / 2)];
  const modal = bounds[fs.indexOf(Math.max(...fs))];
  const parts = [];
  if (fs.filter(f => f === Math.max(...fs)).length === 1) parts.push({ lab: '', q: 'Write down the modal class.', marks: 1, ans: `${modal[0]} < ${v(unit[1])} ≤ ${modal[1]}`, ms: [B('cao')], space: 0.5 });
  parts.push({ lab: '', q: 'Write down the class interval that contains the median.', marks: 1, ans: `${medClass[0]} < ${v(unit[1])} ≤ ${medClass[1]}`, ms: [B('cao')], space: 1 });
  parts.push({ lab: '', q: `Work out an estimate for the mean.${isInt(est * 10) ? '' : ' Give your answer correct to 1 decimal place.'}`, marks: 3, ans: `${isInt(est * 10) ? N(est) : N(est, 1)} ${un}`, line: { post: un }, ms: [M(`for using midpoints ${mids.join(', ')} and at least 3 products f × midpoint`), M(`for ${N(sfx)} ÷ ${tot}`), A(`for ${isInt(est * 10) ? N(est) : N(est, 1)}`)], space: 3 });
  if (band === 3) parts.push({ lab: '', q: `Explain why your answer is only an estimate.`, marks: 1, ans: 'The actual values are not known; the midpoint of each class has been used.', ms: [C('for “midpoints used” or “actual values not known”')], line: null, space: 1 });
  parts.forEach((p, i) => p.lab = '(' + 'abcd'[i] + ')');
  return { stem: `The table shows some information about the ${unit[0].split(',')[0].toLowerCase()} of ${tot} ${unit[1] === 't' ? 'phone calls' : unit[1] === 'm' ? 'apples' : 'plants'}.`, fig, parts, calc: isInt(est * 10) ? undefined : 'either' };
});

gen('s_charts', 'Statistics', 'Bar charts & pie charts', { F: [1, 2], H: [], calc: 'nocalc', spec: 'S2' }, (r, band) => {
  if (band === 1) {
    const cats = r.pick([['Football', 'Rugby', 'Tennis', 'Swimming', 'Netball'], ['Cat', 'Dog', 'Fish', 'Rabbit', 'Hamster']]);
    const vals = cats.map(() => r.int(2, 14));
    const fig = barChart(cats, vals, { ymax: 16, ystep: 2, yminor: 1, yTitle: 'Number of students', uy: 12.5 });
    const top = cats[vals.indexOf(Math.max(...vals))];
    if (vals.filter(x => x === Math.max(...vals)).length > 1) return null;
    const [i, j] = r.sample([0, 1, 2, 3, 4], 2);
    if (vals[i] === vals[j]) return null; // "how many more" would have the answer 0
    return { stem: `The bar chart shows information about the favourite ${cats[0] === 'Cat' ? 'pet' : 'sport'} of some students.`, fig, parts: [
      { lab: '(a)', q: `Which ${cats[0] === 'Cat' ? 'pet' : 'sport'} is the most popular?`, marks: 1, ans: top, ms: [B('cao')], space: 0.5 },
      { lab: '(b)', q: `How many more students chose ${cats[i]} than ${cats[j]}?`.replace('more', vals[i] >= vals[j] ? 'more' : 'fewer'), marks: 1, ans: String(Math.abs(vals[i] - vals[j])), ms: [B('cao')], space: 1 },
      { lab: '(c)', q: 'How many students are there altogether?', marks: 1, ans: String(vals.reduce((a, b) => a + b, 0)), ms: [B('cao')], space: 1 }] };
  }
  // pie chart angles
  const tot = r.pick([36, 45, 60, 72, 90, 120]);
  const per = 360 / tot;
  const cats = r.pick([['Bus', 'Car', 'Walk', 'Bike'], ['Pizza', 'Pasta', 'Curry', 'Salad']]);
  let f; do { f = cats.map(() => r.int(Math.round(tot / 10), Math.round(tot / 2.5))); f[3] = tot - f[0] - f[1] - f[2]; } while (f[3] < 2);
  const fig = table([[cats[0] === 'Bus' ? 'Travel' : 'Food', 'Frequency', 'Angle'], ...cats.map((c, i) => [c, f[i], ''])]);
  const showPie = pieChart(cats, f.map(x => x * per), { showAngles: true });
  return { stem: `${tot} people were asked to choose their favourite ${cats[0] === 'Bus' ? 'way to travel to work' : 'food'}. The table shows their answers.`, fig, parts: [
    { lab: '(a)', q: 'Work out the angle for each sector of a pie chart. Write your answers in the table.', marks: 2, ans: cats.map((c, i) => `${c} ${N(f[i] * per)}°`).join(', '), ms: [M(`for 360 ÷ ${tot} = ${N(per)} or one correct angle`), A('for all angles correct')], line: null, space: 2 },
    (() => { const ang = r.pick([45, 60, 72, 80, 90, 108, 120, 135, 150]); const base = 360 / gcd(ang, 360); let G2 = base; while (G2 < 60) G2 += base; return { lab: '(b)', q: `A pie chart for a different group of ${G2} people has an angle of ${ang}° for ${cats[1]}. How many people in this group chose ${cats[1]}?`, marks: 2, ans: N(ang / 360 * G2), ms: [M(`for ${ang} ÷ 360 × ${G2}`), A()], space: 2 }; })()] };
});

gen('s_scatter', 'Statistics', 'Scatter graphs', { F: [2], H: [2], calc: 'nocalc', spec: 'S6' }, (r, band) => {
  const pos = r.chance(0.6);
  const ctx2 = pos ? r.pick([['Hours of revision', 'Test score (%)', 0, 20, 2, 20, 100, 10]]) : r.pick([['Age of car (years)', 'Value (£1000s)', 0, 10, 1, 0, 20, 2]]);
  const [xt, yt, x0, x1, xs, y0, y1, ys] = ctx2;
  const m = pos ? (y1 - y0 - 25) / (x1 - x0) : -(y1 - y0 - 4) / (x1 - x0), c = pos ? y0 + 15 : y1 - 2;
  const pts = [];
  for (let i = 0; i < 12; i++) { const x = clean(roundDp(x0 + 0.5 + (x1 - x0 - 1) * (i + r.r() * 0.6) / 12, 1)); const y = clean(roundDp(m * x + c + (r.r() - 0.5) * (y1 - y0) * 0.12, 0)); if (y > y0 && y < y1) pts.push([x, y]); }
  const snap = (v0, st) => clean(Math.round(v0 / st) * st);
  const outX = snap(x0 + (x1 - x0) * r.pick([0.2, 0.25, 0.3, 0.65, 0.7, 0.75]), xs), outY = snap(roundDp(pos ? y0 + (y1 - y0) * (m * outX + c > (y0 + y1) / 2 ? 0.2 : 0.85) : y0 + (y1 - y0) * (m * outX + c > (y0 + y1) / 2 ? 0.15 : 0.9), 0), ys / 2);
  pts.push([outX, outY]);
  const fig = scatterChart(pts, { xmin: x0, xmax: x1, ymin: y0, ymax: y1, xstep: xs * 2, xminor: xs, ystep: ys, yminor: ys / 2, ux: 300 / (x1 - x0), uy: 220 / (y1 - y0), xTitle: xt, yTitle: yt });
  let xq; do { xq = clean(roundDp(x0 + (x1 - x0) * r.pick([0.35, 0.45, 0.55, 0.6]), 0)); } while (xq === outX);
  const est = m * xq + c;
  const fu = (x) => pos ? N(roundDp(x, 0)) : money(Math.round(x * 2) * 500); // car values are in £1000s on the graph
  return { stem: `The scatter graph shows information about ${pos ? 'the number of hours some students spent revising and their test scores' : 'the ages and values of some cars'}.`, fig, parts: [
    { lab: '(a)', q: 'One of the points is an outlier. Write down the coordinates of the outlier.', marks: 1, ans: `(${N(outX)}, ${N(outY)})`, ms: [B('cao')], space: 0.5 },
    { lab: '(b)', q: `Ignoring the outlier, describe the relationship between ${pos ? 'the hours of revision and the test score' : 'the age of a car and its value'}.`, marks: 1, ans: pos ? `Positive correlation: the more hours of revision, the higher the score.` : `Negative correlation: the older the car, the lower its value.`, ms: [B(`for ${pos ? 'positive' : 'negative'} correlation or a description in context`)], line: null, space: 1 },
    { lab: '(c)', q: `${pos ? 'A student revised' : 'A car is'} for ${N(xq)} ${pos ? 'hours' : 'years old'}. Use a line of best fit to estimate ${pos ? 'the test score' : 'its value'}.`.replace('A car is for', 'A car is').replace(' years old.', ' years old.'), marks: 2, ans: `about ${fu(est)} (accept ${fu(est - (y1 - y0) * 0.08)} to ${fu(est + (y1 - y0) * 0.08)})`, ms: [M('for a line of best fit drawn (or used)'), A(`for an answer in the range ${fu(est - (y1 - y0) * 0.08)} to ${fu(est + (y1 - y0) * 0.08)}`)], line: pos ? { post: '%' } : { pre: '£' }, space: 1 }] };
});

gen('s_cumfreq', 'Statistics', 'Cumulative frequency & box plots', { F: [], H: [3], calc: 'nocalc', spec: 'S3, S4' }, (r, band) => {
  // grouped data with smooth CF curve drawn
  const w = r.pick([10, 20]), k = 6, tot = r.pick([60, 80, 120]);
  let fs; do { const shape = [0.05, 0.15, 0.3, 0.3, 0.15, 0.05].map(p => p * (0.7 + r.r() * 0.6)); const s = shape.reduce((a, b) => a + b, 0); fs = shape.map(p => Math.round(p / s * tot)); fs[2] += tot - fs.reduce((a, b) => a + b, 0); } while (fs.some(f => f < 1));
  const ub = Array.from({ length: k }, (_, i) => (i + 1) * w);
  const cum = []; fs.reduce((s, f, i) => (cum[i] = s + f), 0);
  const pts = [[0, 0]].concat(ub.map((u, i) => [u, cum[i]]));
  // monotone piecewise cubic (Fritsch–Carlson) through the points
  const xsP = pts.map(p => p[0]), ysP = pts.map(p => p[1]);
  const dk = []; for (let i = 0; i < pts.length - 1; i++) dk.push((ysP[i + 1] - ysP[i]) / (xsP[i + 1] - xsP[i]));
  const mk = [dk[0]]; for (let i = 1; i < pts.length - 1; i++) mk.push(dk[i - 1] * dk[i] <= 0 ? 0 : (dk[i - 1] + dk[i]) / 2); mk.push(dk[dk.length - 1]);
  for (let i = 0; i < dk.length; i++) { if (dk[i] === 0) { mk[i] = mk[i + 1] = 0; continue; } const a = mk[i] / dk[i], b = mk[i + 1] / dk[i], h = a * a + b * b; if (h > 9) { const t = 3 / Math.sqrt(h); mk[i] = t * a * dk[i]; mk[i + 1] = t * b * dk[i]; } }
  const f = (x) => { let i = Math.min(Math.floor(x / w), pts.length - 2); i = Math.max(0, i); const h = xsP[i + 1] - xsP[i], t = (x - xsP[i]) / h; const h00 = 2 * t ** 3 - 3 * t * t + 1, h10 = t ** 3 - 2 * t * t + t, h01 = -2 * t ** 3 + 3 * t * t, h11 = t ** 3 - t * t; return h00 * ysP[i] + h10 * h * mk[i] + h01 * ysP[i + 1] + h11 * h * mk[i + 1]; };
  const inv = (yv) => { let lo = 0, hi = ub[k - 1]; for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (f(m) < yv) lo = m; else hi = m; } return (lo + hi) / 2; };
  const med = inv(tot / 2), lq = inv(tot / 4), uq = inv(3 * tot / 4);
  const ystep = tot >= 100 ? 20 : 10;
  const ax = Axes({ xmin: 0, xmax: ub[k - 1], ymin: 0, ymax: tot, ux: 330 / ub[k - 1], uy: 220 / tot, xstep: w, xminor: w / 5, ystep, yminor: ystep / 5, xTitle: 'Time (minutes)', yTitle: 'Cumulative frequency' });
  ax.plot(f, 0, ub[k - 1]); ax.crosses(pts.slice(1));
  const fig = ax.svg('Cumulative frequency graph');
  const tol = w / 5;
  const valX = ub[Math.floor(k / 2)] + w / 2, above = tot - Math.round(f(valX));
  const iqrR = roundDp(uq, 0) - roundDp(lq, 0);
  return { stem: `The cumulative frequency graph shows information about the times, in minutes, that ${tot} people took to complete a puzzle.`, fig, parts: [
    { lab: '(a)', q: 'Use the graph to find an estimate for the median time.', marks: 1, ans: `${N(roundDp(med, 0))} minutes (±${N(tol / 2)})`, ms: [B(`for ${N(roundDp(med - tol / 2, 0))} to ${N(roundDp(med + tol / 2, 0))}`)], line: { post: 'minutes' }, space: 1 },
    { lab: '(b)', q: 'Use the graph to find an estimate for the interquartile range.', marks: 2, ans: `${N(iqrR)} minutes (UQ ≈ ${N(roundDp(uq, 0))}, LQ ≈ ${N(roundDp(lq, 0))})`, ms: [M(`for reading at ${tot * 3 / 4} and ${tot / 4} (≈ ${N(roundDp(uq, 0))} and ${N(roundDp(lq, 0))})`), A(`for ${N(iqrR - tol)} to ${N(iqrR + tol)}`)], line: { post: 'minutes' }, space: 2 },
    { lab: '(c)', q: `Use the graph to find an estimate for the number of people who took more than ${N(valX)} minutes.`, marks: 2, ans: `${N(Math.round(above))} (accept ±${Math.max(2, Math.round(tot / 30))})`, ms: [M(`for reading at ${N(valX)} minutes (≈ ${N(Math.round(f(valX)))})`), A(`for ${N(Math.round(above) - Math.max(2, Math.round(tot / 30)))} to ${N(Math.round(above) + Math.max(2, Math.round(tot / 30)))}`)], space: 2 }] };
});

gen('s_boxplot', 'Statistics', 'Comparing distributions (box plots)', { F: [], H: [2, 3], calc: 'nocalc', spec: 'S4' }, (r, band) => {
  const mk = () => { const mn = r.int(5, 20), q1 = mn + r.int(4, 12), md = q1 + r.int(3, 10), q3 = md + r.int(3, 12), mx = q3 + r.int(4, 15); return { min: mn, q1, med: md, q3, max: mx }; };
  const A_ = mk(), B_ = mk();
  if (A_.med === B_.med || (A_.q3 - A_.q1) === (B_.q3 - B_.q1)) return null;
  const top = Math.ceil(Math.max(A_.max, B_.max) / 10) * 10 + 10;
  const fig = boxPlotFig([Object.assign({ label: 'Class A' }, A_), Object.assign({ label: 'Class B' }, B_)], { xmin: 0, xmax: top, step: 10, minor: 2, unit: Math.min(7, 380 / top), title: 'Test mark' });
  const iqrA = A_.q3 - A_.q1, iqrB = B_.q3 - B_.q1;
  return { stem: 'The box plots show information about the test marks of students in Class A and Class B.', fig, parts: [
    { lab: '(a)', q: 'Work out the interquartile range for Class A.', marks: 1, ans: String(iqrA), ms: [B('cao')], space: 1 },
    { lab: '(b)', q: 'Compare the distributions of the marks for Class A and Class B.', marks: 2, ans: `The median for Class ${A_.med > B_.med ? 'A' : 'B'} (${Math.max(A_.med, B_.med)}) is higher than Class ${A_.med > B_.med ? 'B' : 'A'} (${Math.min(A_.med, B_.med)}), so on average Class ${A_.med > B_.med ? 'A' : 'B'} did better. The IQR for Class ${iqrA < iqrB ? 'A' : 'B'} (${Math.min(iqrA, iqrB)}) is smaller than Class ${iqrA < iqrB ? 'B' : 'A'} (${Math.max(iqrA, iqrB)}), so Class ${iqrA < iqrB ? 'A' : 'B'}'s marks are more consistent.`, ms: [B('for a correct comparison of medians in context'), B('for a correct comparison of interquartile ranges (or ranges) in context')], line: null, space: 3 }] };
});

gen('s_histogram', 'Statistics', 'Histograms', { F: [], H: [3, 4], calc: 'nocalc', spec: 'S3' }, (r, band) => {
  const classes = r.pick([[[0, 10], [10, 15], [15, 20], [20, 30], [30, 50]], [[0, 20], [20, 30], [30, 40], [40, 60], [60, 100]], [[0, 5], [5, 10], [10, 20], [20, 30], [30, 40]]]);
  let fd; do { fd = classes.map(() => r.int(2, 16) / 2 * (classes[0][1] > 10 ? 0.5 : 1)); } while (fd.some((d, i) => !isInt(d * (classes[i][1] - classes[i][0]))));
  const freq = classes.map(([a, b], i) => fd[i] * (b - a));
  const hide = r.int(1, 4);
  const xmax = classes[classes.length - 1][1];
  const ymax = Math.ceil(Math.max(...fd) + 1);
  const fig = histogramFig(classes, fd.map((d, i) => (band === 3 && i === hide) ? null : d), { xmin: 0, xmax, ymax, ux: 330 / xmax, uy: 200 / ymax, xstep: xmax / 5 > 10 ? 20 : 10, xminor: xmax > 50 ? 5 : 2, ystep: ymax > 10 ? 2 : 1, yminor: ymax > 10 ? 0.5 : 0.25, xTitle: 'Time (seconds)' });
  const tbl = table([['Time (<i>t</i> seconds)', 'Frequency'], ...classes.map(([a, b], i) => [`${a} < <i>t</i> ≤ ${b}`, (band === 3 ? (i === hide ? freq[i] : '') : freq[i])])]);
  const total = freq.reduce((a, b) => a + b, 0);
  if (band === 3) {
    return { stem: `The table and the histogram show information about the times, in seconds, some people took to answer a question.`, fig: tbl + '<div class="inline-fig">' + fig + '</div>', parts: [
      { lab: '(a)', q: 'Use the histogram to complete the table.', marks: 2, ans: classes.map(([a, b], i) => i === hide ? null : `${a}–${b}: ${N(freq[i])}`).filter(Boolean).join(', '), ms: [M('for using frequency = frequency density × class width (one correct value)'), A('for all values correct')], line: null, space: 1 },
      { lab: '(b)', q: `Use the table to complete the histogram.`, marks: 1, ans: `Bar for ${classes[hide][0]} < t ≤ ${classes[hide][1]} with height ${N(fd[hide])}`, ms: [B(`for a bar of frequency density ${N(fd[hide])}`)], line: null, space: 0.5 }] };
  }
  // band 4: estimate number in a range
  const lo = classes[1][0] + (classes[1][1] - classes[1][0]) / 2, hi = classes[3][0] + (classes[3][1] - classes[3][0]) / 2;
  let est = 0; classes.forEach(([a, b], i) => { const o = Math.max(0, Math.min(b, hi) - Math.max(a, lo)); est += o * fd[i]; });
  est = clean(est); if (!isInt(est)) return null;
  return { stem: 'The histogram shows information about the times, in seconds, that some people took to answer a question.', fig, parts: [
    { lab: '(a)', q: 'Work out the total number of people.', marks: 2, ans: N(total), ms: [M('for frequency = frequency density × class width for at least 3 classes'), A()], space: 2 },
    { lab: '(b)', q: `Work out an estimate for the number of people who took between ${N(lo)} and ${N(hi)} seconds.`, marks: 2, ans: N(est), ms: [M('for using the parts of the bars between the two values (area)'), A(`for ${N(est)}`)], space: 2 }] };
});

gen('s_sampling', 'Statistics', 'Sampling & capture–recapture', { F: [], H: [3], calc: 'either', spec: 'S1' }, (r, band) => {
  const m1 = r.pick([30, 40, 50, 60, 80]), m2 = r.pick([40, 50, 60]), k = r.int(4, 12);
  const N_ = m1 * m2 / k;
  if (!isInt(N_)) return null;
  const [tot, samp] = r.pick([[600, 50], [600, 60], [800, 50], [800, 80], [1200, 50], [1200, 60], [1200, 80]]);
  const u = tot / samp, years = [u * r.int(Math.ceil(150 / u), Math.floor(250 / u)), u * r.int(Math.ceil(150 / u), Math.floor(250 / u))]; years.push(tot - years[0] - years[1]);
  const st = years.map(y => y / tot * samp);
  return { parts: [
    { lab: '(a)', q: `Lena wants to estimate the number of fish in a pond. She catches ${m1} fish, marks them and puts them back. Later she catches ${m2} fish. ${k} of these fish are marked.<br>Work out an estimate for the number of fish in the pond.`, marks: 2, ans: N(N_), ms: [M(`for ${fr(k, m2)} = ${fr(m1, v('N'))} or ${m1} × ${m2} ÷ ${k}`), A()], space: 2 },
    { lab: '(b)', q: `State one assumption Lena made.`, marks: 1, ans: 'The population did not change between the two samples (no fish were born, died, joined or left), or marks did not come off, or fish mixed randomly.', ms: [C('for a sensible assumption')], line: null, space: 1 },
    { lab: '(c)', q: `A school has ${tot} students: ${years[0]} in Year 9, ${years[1]} in Year 10 and ${years[2]} in Year 11. A sample of ${samp} students is stratified by year group.<br>How many Year 10 students should be in the sample?`, marks: 2, ans: N(st[1]), ms: [M(`for ${years[1]} ÷ ${tot} × ${samp}`), A()], space: 2 }] };
});

// ======================= RATIO, PROPORTION AND RATES OF CHANGE =======================
'use strict';
const NAMES = ['Amir', 'Bella', 'Chloe', 'Dev', 'Ella', 'Finn', 'Grace', 'Harry', 'Isla', 'Jamal', 'Kasim', 'Lily', 'Mia', 'Noah', 'Ola', 'Priya', 'Ravi', 'Sana', 'Tom', 'Zara'];
const SHE = new Set(['Bella', 'Chloe', 'Ella', 'Grace', 'Isla', 'Lily', 'Mia', 'Ola', 'Priya', 'Sana', 'Zara']);
const pron = (n) => SHE.has(n) ? 'she' : 'he';
const poss = (n) => SHE.has(n) ? 'her' : 'his';

gen('r_ratio', 'Ratio & Proportion', 'Ratio', { F: [1, 2], H: [2, 3], calc: 'nocalc', spec: 'R4, R5, R8' }, (r, band) => {
  const parts = [];
  if (band === 1) {
    const g = r.int(2, 9), a = r.int(1, 7), b = r.int(2, 9);
    if (gcd(a, b) !== 1 || a === b) return null;
    parts.push({ lab: '(a)', q: `Write the ratio ${a * g} : ${b * g} in its simplest form.`, marks: 1, ans: `${a} : ${b}`, ms: [B('cao')], space: 1 });
    let p, q; do { p = r.int(1, 5); q = r.int(2, 7); } while (gcd(p, q) !== 1 || p === q);
    const tot = (p + q) * r.int(3, 12) * r.pick([1, 5, 10]);
    const [n1, n2] = r.sample(NAMES, 2);
    parts.push({ lab: '(b)', q: `${n1} and ${n2} share ${money(tot)} in the ratio ${p} : ${q}<br>Work out how much money ${n1} gets.`, marks: 2, ans: money(tot / (p + q) * p), ms: [M(`for ${money(tot)} ÷ ${p + q} (= ${money(tot / (p + q))})`), A()], line: { pre: '£' }, space: 2 });
    return { parts };
  }
  if (band === 2) {
    let p, q; do { p = r.int(2, 5); q = r.int(3, 9); } while (gcd(p, q) !== 1 || p >= q);
    const k = r.int(3, 12), diff = (q - p) * k;
    const thing = r.pick([['boys', 'girls', 'students', 'in a club', 'in the club'], ['red counters', 'blue counters', 'counters', 'in a bag', 'in the bag'], ['cats', 'dogs', 'animals', 'at a rescue centre', 'at the rescue centre']]);
    parts.push({ lab: '(a)', q: `There are only ${thing[0]} and ${thing[1]} ${thing[3]}. The ratio of ${thing[0]} to ${thing[1]} is ${p} : ${q}. There are ${diff} more ${thing[1]} than ${thing[0]}.<br>How many ${thing[2]} are there ${thing[4]} altogether?`, marks: 3, ans: N((p + q) * k), ms: [P(`for ${q} − ${p} = ${q - p} part${q - p === 1 ? '' : 's'}`), P(`for ${diff} ÷ ${q - p} (= ${k})`), A(`for ${(p + q) * k}`)], space: 3 });
    parts.push({ lab: '(b)', q: `What fraction of the ${thing[2]} ${thing[4]} are ${thing[0]}?`, marks: 1, ans: new Frac(p, p + q).html(), ms: [B(`for ${fr(p, p + q)} oe`)], space: 1 });
    return { parts };
  }
  // band 3: combine ratios
  let a, b, b2, c; do { a = r.int(1, 5); b = r.int(2, 6); b2 = r.int(1, 5); c = r.int(1, 6); } while (gcd(a, b) !== 1 || gcd(b2, c) !== 1 || b === b2);
  const L = lcm(b, b2), A_ = a * L / b, B_ = L, C_ = c * L / b2;
  const k = r.int(2, 9), total = (A_ + B_ + C_) * k;
  const [x, y, z, where, noun] = r.pick([['apples', 'oranges', 'pears', 'In a fruit box', 'pieces of fruit'], ['red beads', 'blue beads', 'green beads', 'In a box of beads', 'beads'], ['cows', 'sheep', 'pigs', 'On a farm', 'animals']]);
  parts.push({ lab: '', q: `${where}, the ratio of ${x} to ${y} is ${a} : ${b}. The ratio of ${y} to ${z} is ${b2} : ${c}. There are ${total} ${noun} altogether. There are only ${x}, ${y} and ${z}.<br>How many ${z} are there?`, marks: 4,
    ans: N(C_ * k), ms: [P(`for scaling to a common middle term: ${a * L / b} : ${L} and ${L} : ${c * L / b2}`), P(`for ${A_} : ${B_} : ${C_}`), P(`for ${total} ÷ ${A_ + B_ + C_} (= ${k})`), A(`for ${C_ * k}`)], space: 4 });
  return { parts };
});

gen('r_proportion', 'Ratio & Proportion', 'Recipes & proportion', { F: [1, 2], H: [2], calc: 'either', spec: 'R10' }, (r, band, ctx) => {
  const recipe = r.pick([
    ['biscuits', [['butter', 'g', 120], ['sugar', 'g', 90], ['flour', 'g', 210], ['eggs', '', 2]], 18],
    ['pancakes', [['flour', 'g', 150], ['milk', 'ml', 300], ['eggs', '', 3]], 12],
    ['scones', [['flour', 'g', 225], ['butter', 'g', 60], ['milk', 'ml', 150]], 10],
    ['flapjacks', [['oats', 'g', 240], ['butter', 'g', 160], ['syrup', 'g', 120]], 16],
  ]);
  const [item, ings, n0] = recipe;
  const n1 = n0 * r.pick([1.5, 2.5, 0.5, 3]) ;
  if (!isInt(n1)) return null;
  const fig = table([['Ingredient', 'Amount']].concat(ings.map(([nm, u, q]) => [nm, `${q}${u ? ' ' + u : ''}`])));
  const name = r.pick(NAMES);
  const k = n1 / n0;
  const parts = [{ lab: '(a)', q: `${name} wants to make ${n1} ${item}. Work out how much ${ings[0][0]} ${pron(name)} needs.`, marks: 2, ans: `${N(ings[0][2] * k)} ${ings[0][1]}`, ms: [M(`for ${ings[0][2]} ÷ ${n0} × ${n1} or ${ings[0][2]} × ${N(k)}`), A()], line: { post: ings[0][1] }, space: 2 }];
  if (band >= 2) {
    // greatest number possible from stock
    const stock = ings.map(([nm, u, q]) => [nm, u, q * r.pick([2, 3, 4, 5]) + (u ? r.int(0, 3) * 10 : 0)]);
    const batches = Math.min(...stock.map((s, i) => Math.floor(s[2] / ings[i][2])));
    if (stock.filter((s, i) => Math.floor(s[2] / ings[i][2]) === batches).length !== 1) return null; // one clear limiting ingredient
    const limit = stock[stock.findIndex((s, i) => Math.floor(s[2] / ings[i][2]) === batches)][0];
    const amt = (q, u, nm) => u ? `${q} ${u} of ${nm}` : `${q} ${nm}`;
    const lim = (nm) => nm + (/s$/.test(nm) ? ' limit' : ' limits');
    parts.push({ lab: '(b)', q: `${name} makes ${item} in batches of ${n0}, using the ingredients above for each batch. ${cap(pron(name))} has ${listAnd(stock.map(s => amt(s[2], s[1], s[0])))}.<br>What is the greatest number of ${item} ${pron(name)} can make? ${cap(pron(name))} only makes whole batches. You must show how you get your answer.`, marks: 3, ans: `${batches * n0} ${item} (${lim(limit)} it to ${batches} batches)`, ms: [P(`for a correct method for at least two ingredients, e.g. ${stock[0][2]} ÷ ${ings[0][2]} = ${N(roundDp(stock[0][2] / ings[0][2], 2))}`), P(`for identifying ${limit} as the limiting ingredient (${batches} batches)`), A(`for ${batches * n0}`)], space: 3 });
    const li = stock.findIndex(x => x[0] === limit), extra = ings[li][2] * r.pick([1, 2]) - (stock[li][2] % ings[li][2]) + (ings[li][1] ? r.pick([-10, 10]) : 0);
    const st2 = stock.map((x, i) => i === li ? x[2] + extra : x[2]);
    const b2 = Math.min(...st2.map((q, i) => Math.floor(q / ings[i][2])));
    const lim2 = stock.filter((x, i) => Math.floor(st2[i] / ings[i][2]) === b2).map(x => x[0]);
    const why = lim2.includes(limit) && lim2.length === 1 ? `the extra ${limit} ${/s$/.test(limit) ? 'are' : 'is'} not enough for another batch` : `${listAnd(lim2.filter(x => x !== limit))} now ${lim2.filter(x => x !== limit).length > 1 || /s$/.test(lim2.filter(x => x !== limit)[0]) ? 'limit' : 'limits'} it to ${b2} batches`;
    parts.push({ lab: '(c)', q: `${name} is given another ${amt(extra, ings[li][1], limit)}. Does this change your answer to part (b)? Give a reason.`, marks: 1, ans: b2 === batches ? `No. ${name} can still only make ${batches * n0} ${item}, because ${why}.` : `Yes. ${name} can now make ${b2 * n0} ${item} (${b2} batches${b2 > batches ? '' : ''}).`, ms: [C(b2 === batches ? `for No with a correct reason, e.g. ${why}` : `for Yes, with ${b2 * n0} ${item} or a correct reason`)], line: null, space: 1.5 });
  }
  return { stem: `Here is a list of ingredients for making ${n0} ${item}.`, fig, parts };
});

gen('r_percent_change', 'Ratio & Proportion', 'Percentage change & interest', { F: [2], H: [2, 3], calc: 'calc', spec: 'R9, R16' }, (r, band) => {
  const parts = [];
  if (band === 2) {
    const buy = r.pick([240, 320, 450, 600, 75, 180, 250, 400, 360, 125]) , pct = r.pick([12, 15, 18, 22, 35, 8, 6, 14, 24, 28, 32]);
    const sell = clean(buy * (1 + r.pick([1, -1]) * pct / 100));
    const name = r.pick(NAMES);
    const prof = sell > buy;
    parts.push({ lab: '(a)', q: `${name} bought a bike for ${money(buy)} and sold it for ${money(sell, !isInt(sell))}.<br>Work out ${name}'s percentage ${prof ? 'profit' : 'loss'}.`, marks: 3, ans: `${pct}%`, ms: [M(`for ${prof ? money(sell, !isInt(sell)) + ' − ' + money(buy) : money(buy) + ' − ' + money(sell, !isInt(sell))} = ${money(Math.abs(sell - buy), !isInt(sell))} or ${N(sell)} ÷ ${buy}`), M(`for ${N(Math.abs(sell - buy))} ÷ ${buy} × 100`), A()], line: { post: '%' }, space: 3 });
    const P_ = r.pick([2000, 3500, 4200, 5000, 8000]), rate = r.pick([1.5, 2, 2.5, 3, 3.2, 4]), yrs = r.int(2, 5);
    const amt = P_ * (1 + rate / 100) ** yrs;
    if (r.chance(0.35)) { // simple interest, then compare with compound
      const si = P_ * rate / 100 * yrs;
      parts.push({ lab: '(b)', q: `${r.pick(NAMES)} invests ${money(P_)} for ${yrs} years at ${N(rate)}% per year <b>simple</b> interest.<br>Work out the total amount of interest earned.`, marks: 2, ans: money(si, !isInt(si)), ms: [M(`for ${N(rate)}% of ${N(P_)} (= ${money(P_ * rate / 100, true)}) × ${yrs}`), A(`for ${money(si, !isInt(si))}`)], line: { pre: '£' }, space: 2 });
      parts.push({ lab: '(c)', q: `How much <b>more</b> interest would be earned in ${yrs} years at ${N(rate)}% per year <b>compound</b> interest?`, marks: 3, ans: money(amt - P_ - si, true), ms: [M(`for ${N(P_)} × ${N(1 + rate / 100)}${sup(yrs)} (= ${money(amt, true)})`), M(`for their total − ${money(P_)} − ${money(si, !isInt(si))}`), A(`for ${money(amt - P_ - si, true)}`)], line: { pre: '£' }, space: 2.5 });
      return { parts, calc: 'calc' };
    }
    parts.push({ lab: '(b)', q: `${r.pick(NAMES)} invests ${money(P_)} in a savings account for ${yrs} years. The account pays ${N(rate)}% compound interest per year.<br>How much money is in the account at the end of ${yrs} years?`, marks: 3, ans: money(amt, true), ms: [M(`for ${N(1 + rate / 100)} seen (multiplier)`), M(`for ${N(P_)} × ${N(1 + rate / 100)}${sup(yrs)}`), A(`for ${money(amt, true)}`)], line: { pre: '£' }, space: 3 });
    return { parts, calc: 'calc' };
  }
  // band 3: depreciation with two rates / comparison
  const v0 = r.pick([12000, 15000, 18500, 22000]), r1 = r.pick([15, 20, 25]), r2 = r.pick([8, 10, 12]), y2 = r.int(2, 3);
  const val = v0 * (1 - r1 / 100) * (1 - r2 / 100) ** y2;
  parts.push({ lab: '(a)', q: `A car cost ${money(v0)} when new. In the first year its value decreased by ${r1}%. In each of the next ${y2} years its value decreased by ${r2}%.<br>Work out the value of the car at the end of ${y2 + 1} years.`, marks: 3, ans: money(val, true), ms: [M(`for ${v0} × ${N(1 - r1 / 100)} (= ${N(v0 * (1 - r1 / 100))})`), M(`for × ${N(1 - r2 / 100)}${sup(y2)}`), A(`for ${money(val, true)}`)], line: { pre: '£' }, space: 3 });
  const inc = r.pick([10, 20, 25, 30]), dec = r.pick([10, 20, 25, 30]);
  if (Math.abs((1 + inc / 100) * (1 - dec / 100) - 1) < 1e-9) return null;
  const overall = clean((1 + inc / 100) * (1 - dec / 100) * 100 - 100);
  parts.push({ lab: '(b)', q: `The price of a games console is increased by ${inc}%. The new price is then decreased by ${dec}%.<br>Work out the overall percentage change in the price. State whether it is an increase or a decrease.`, marks: 2, ans: overall === 0 ? 'No change (0%)' : `${N(Math.abs(overall))}% ${overall > 0 ? 'increase' : 'decrease'}`, ms: [M(`for ${N(1 + inc / 100)} × ${N(1 - dec / 100)} (= ${N(clean((1 + inc / 100) * (1 - dec / 100)))})`), A()], space: 2 });
  return { parts, calc: 'calc' };
});

gen('r_reverse_percent', 'Ratio & Proportion', 'Reverse percentages', { F: [2], H: [2, 3], calc: 'either', needCalc: [3], spec: 'R9' }, (r, band, ctx) => {
  const parts = [];
  const pct = r.pick(ctx.calc ? [12, 15, 18, 35, 8] : [10, 20, 25, 40]);
  const orig = ctx.calc ? r.int(60, 400) : r.pick([40, 60, 80, 120, 160, 200, 240]);
  const sale = clean(orig * (1 - pct / 100));
  const item = r.pick(['jacket', 'tablet', 'pair of trainers', 'lamp']);
  parts.push({ lab: '(a)', q: `In a sale, normal prices are reduced by ${pct}%. The sale price of a ${item} is ${money(sale, !isInt(sale))}.<br>Work out the normal price of the ${item}.`, marks: 3, ans: money(orig), ms: [M(`for ${100 - pct}% = ${money(sale, !isInt(sale))}`), M(`for ${N(sale)} ÷ ${N((100 - pct) / 100)} or ${N(sale)} ÷ ${100 - pct} × 100`), A()], line: { pre: '£' }, space: 3 });
  const name = r.pick(NAMES);
  const wrong = clean(sale * (1 + pct / 100));
  parts.push({ lab: '(b)', q: `${name} says, “To find the normal price, add ${pct}% of ${money(sale, !isInt(sale))} to ${money(sale, !isInt(sale))}.” Explain why ${name} is wrong.`, marks: 1, ans: `The ${pct}% was taken off the normal price, not the sale price, so ${money(sale, !isInt(sale))} is ${100 - pct}% of the normal price. (${name}'s method gives ${money(wrong, true)}.)`, ms: [C(`for a correct explanation, e.g. ${money(sale, !isInt(sale))} is ${100 - pct}% of the original price, not 100%`)], line: null, space: 1.5 });
  if (band === 3) {
    const r2 = r.pick([2, 3, 4, 5]), yrs = 2, P_ = r.pick([5000, 6400, 8000, 12500]);
    const after = P_ * (1 + r2 / 100) ** yrs;
    parts.push({ lab: '(c)', q: `After ${yrs} years of ${r2}% compound interest per year, there is ${money(after, true)} in a bank account. No other money was paid in or taken out.<br>How much money was put into the account at the start?`, marks: 2, ans: money(P_), ms: [M(`for ${money(after, true)} ÷ ${N(1 + r2 / 100)}${sup(yrs)}`), A()], line: { pre: '£' }, space: 2 });
    return { parts, calc: 'calc' };
  }
  return { parts };
});

gen('r_compound_measures', 'Ratio & Proportion', 'Speed, density & pressure', { F: [2], H: [2, 3], calc: 'either', needCalc: [3], spec: 'R11' }, (r, band, ctx) => {
  const parts = [];
  if (band === 2) {
    const sp = r.pick([40, 48, 50, 60, 64, 72]), hh = r.int(1, 3), mm = r.pick([15, 30, 45]);
    const d = sp * (hh + mm / 60);
    const name = r.pick(NAMES);
    parts.push({ lab: '(a)', q: `${name} drives ${N(d)} km. The journey takes ${hh} hour${hh > 1 ? 's' : ''} ${mm} minutes.<br>Work out ${name}'s average speed in km/h.`, marks: 3, ans: `${sp} km/h`, ms: [M(`for ${hh} h ${mm} min = ${N(hh + mm / 60)} hours`), M(`for ${N(d)} ÷ ${N(hh + mm / 60)}`), A()], line: { post: 'km/h' }, space: 3 });
    const dens = r.pick([2.5, 7.8, 8.9, 0.8, 1.2, 11.3]), vol = r.pick([20, 40, 50, 120, 250]);
    parts.push({ lab: '(b)', q: `A metal block has a volume of ${vol} cm${sup(3)}. The density of the metal is ${N(dens)} g/cm${sup(3)}.<br>Work out the mass of the block.`, marks: 2, ans: `${N(dens * vol)} g`, ms: [M(`for ${N(dens)} × ${vol}`), A()], line: { post: 'g' }, space: 2 });
    return { parts };
  }
  // band 3: pressure with formula, cuboid on floor
  const F_ = r.pick([180, 240, 300, 420, 600]), a = clean(r.int(12, 40) / 10), b = clean(r.int(8, 25) / 10);
  const P_ = F_ / (a * b);
  parts.push({ lab: '(a)', q: `<div class="rulebox">pressure = ${fr('force', 'area')}</div>A box rests on a floor. The face of the box in contact with the floor is a rectangle ${N(a)} m by ${N(b)} m. The force exerted by the box on the floor is ${F_} newtons.<br>Work out the pressure on the floor due to the box. Give your answer in newtons/m${sup(2)}, correct to 3 significant figures.`, marks: 3, ans: `${SF(P_, 3)} N/m²`, ms: [M(`for area = ${N(a)} × ${N(b)} (= ${N(clean(a * b))})`), M(`for ${F_} ÷ ${N(clean(a * b))}`), A(`for ${SF(P_, 3)}`)], line: { post: 'N/m²' }, space: 3 });
  const d1 = r.int(30, 80), s1 = r.pick([40, 50, 60]), d2 = r.int(40, 120), s2 = r.pick([70, 80, 90]);
  const avg = (d1 + d2) / (d1 / s1 + d2 / s2);
  parts.push({ lab: '(b)', q: `A train travels ${d1} km at an average speed of ${s1} km/h. It then travels a further ${d2} km at an average speed of ${s2} km/h.<br>Work out the average speed for the whole journey. Give your answer correct to 1 decimal place.`, marks: 4, ans: `${N(roundDp(avg, 1), 1)} km/h`, ms: [P(`for time ${d1} ÷ ${s1} (= ${N(roundDp(d1 / s1, 3))} h)`), P(`for time ${d2} ÷ ${s2} (= ${N(roundDp(d2 / s2, 3))} h)`), P(`for ${d1 + d2} ÷ (their total time)`), A(`for ${N(roundDp(avg, 1), 1)}`)], line: { post: 'km/h' }, space: 4 });
  return { parts, calc: 'calc' };
});

gen('r_direct_inverse', 'Ratio & Proportion', 'Direct & inverse proportion', { F: [2], H: [2, 3, 4], calc: 'nocalc', spec: 'R10, R13' }, (r, band) => {
  if (band === 2) {
    const k = r.int(2, 9), x1 = r.int(2, 6), x2 = r.int(7, 15);
    const workers = r.int(3, 6), days = r.pick([12, 18, 24, 30, 36, 40, 60]);
    const w2 = r.pick([2, 3, 4, 5, 6, 8, 9, 10].filter(w => w !== workers && (workers * days) % w === 0));
    const parts = [
      { lab: '(a)', q: `${Y} is directly proportional to ${X}. When ${X} = ${x1}, ${Y} = ${k * x1}.<br>Find the value of ${Y} when ${X} = ${x2}.`, marks: 2, ans: N(k * x2), ms: [M(`for ${Y} = ${k}${X} or ${k * x1} ÷ ${x1} × ${x2}`), A()], line: { pre: Y + ' = ' }, space: 2 },
    ];
    if (w2) parts.push({ lab: '(b)', q: `It takes ${workers} builders ${days} days to build a wall. All the builders work at the same rate.<br>How many days would it take ${w2} builders to build the same wall?`, marks: 2, ans: `${workers * days / w2} days`, ms: [M(`for ${workers} × ${days} (= ${workers * days} builder-days)`), A()], line: { post: 'days' }, space: 2 });
    return { parts };
  }
  if (band === 3) {
    const sq = r.chance(0.5);
    const k = r.int(2, 5), x1 = r.int(2, 5), x2 = r.int(6, 10);
    if (sq) {
      const y1 = k * x1 * x1;
      return { parts: [
        { lab: '(a)', q: `${Y} is directly proportional to ${X}${sup(2)}. When ${X} = ${x1}, ${Y} = ${y1}.<br>Find a formula for ${Y} in terms of ${X}.`, marks: 3, ans: `${Y} = ${k}${X}${sup(2)}`, ms: [M(`for ${Y} = ${v('k')}${X}${sup(2)}`), M(`for ${y1} = ${v('k')} × ${x1}${sup(2)}`), A(`for ${Y} = ${k}${X}${sup(2)}`)], line: { pre: '' }, space: 3 },
        { lab: '(b)', q: `Work out the value of ${Y} when ${X} = ${x2}.`, marks: 1, ans: N(k * x2 * x2), ms: [B('ft their formula')], line: { pre: Y + ' = ' }, space: 1 }] };
    }
    const c = k * 36, y1 = c / (x1 * x1);
    const t1 = r.pick([2, 3, 6]), t2 = r.pick([1, 2, 3, 4, 6, 12].filter(z => z !== t1));
    return { parts: [
      { lab: '(a)', q: `${v('d')} is inversely proportional to ${v('t')}${sup(2)}. When ${v('t')} = ${t1}, ${v('d')} = ${N(c / (t1 * t1))}.<br>Find a formula for ${v('d')} in terms of ${v('t')}.`, marks: 3, ans: `${v('d')} = ${fr(c, v('t') + sup(2))}`, ms: [M(`for ${v('d')} = ${fr(v('k'), v('t') + sup(2))}`), M(`for ${N(c / (t1 * t1))} = ${fr(v('k'), t1 + sup(2))}`), A(`for ${v('d')} = ${fr(c, v('t') + sup(2))}`)], line: { pre: '' }, space: 3 },
      { lab: '(b)', q: `Work out the value of ${v('d')} when ${v('t')} = ${t2}.`, marks: 1, ans: N(clean(c / (t2 * t2))), ms: [B('ft their formula')], line: { pre: v('d') + ' = ' }, space: 1 }] };
  }
  // band 4: percentage change reasoning
  const pow = r.pick([2, 3]), p = r.pick(pow === 3 ? [10, 20, 50] : [10, 20, 25, 50]);
  const factor = (1 + p / 100) ** pow;
  const pc = clean((factor - 1) * 100);
  return { parts: [{ lab: '', q: `${v('P')} is directly proportional to ${v('r')}${sup(pow)}. ${v('r')} is increased by ${p}%.<br>Work out the percentage increase in ${v('P')}.`, marks: 3, ans: `${N(pc)}%`, ms: [M(`for ${v('P')} = ${v('k')}${v('r')}${sup(pow)}`), M(`for ${N(1 + p / 100)}${sup(pow)} (= ${N(factor)})`), A(`for ${N(pc)}`)], line: { post: '%' }, space: 3 }] };
});

gen('r_units', 'Ratio & Proportion', 'Units & conversions', { F: [1, 2], H: [2], calc: 'either', spec: 'N13, R1' }, (r, band, ctx) => {
  const parts = [];
  const kg = clean(r.int(12, 95) / 10), cm = r.int(120, 950), ml = r.int(1200, 8500);
  parts.push({ lab: '(a)', q: `Change ${N(kg)} kg into grams.`, marks: 1, ans: `${N(kg * 1000)} g`, ms: [B('cao')], line: { post: 'g' }, space: 0.5 });
  parts.push({ lab: '(b)', q: `Change ${cm} cm into metres.`, marks: 1, ans: `${N(cm / 100)} m`, ms: [B('cao')], line: { post: 'm' }, space: 0.5 });
  if (band === 1) {
    parts.push({ lab: '(c)', q: `Change ${N(ml)} ml into litres.`, marks: 1, ans: `${N(ml / 1000)} litres`, ms: [B('cao')], line: { post: 'litres' }, space: 0.5 });
    const h = clean(r.int(2, 9) + r.pick([0.25, 0.5, 0.75, 0.2, 0.4]));
    parts.push({ lab: '(d)', q: `Change ${N(h)} hours into hours and minutes.`, marks: 1, ans: `${Math.floor(h)} hours ${Math.round((h % 1) * 60)} minutes`, ms: [B('cao')], line: null, space: 0.5 });
    return { parts };
  }
  const m2 = clean(r.int(2, 9) + r.pick([0, 0.5, 0.25]));
  parts.push({ lab: '(c)', q: `Change ${N(m2)} m${sup(2)} into cm${sup(2)}.`, marks: 1, ans: `${N(m2 * 10000)} cm²`, ms: [B('cao')], line: { post: 'cm²' }, space: 1 });
  const kmh = r.pick([36, 54, 72, 90, 108, 126]);
  parts.push({ lab: '(d)', q: `A car is travelling at ${kmh} km/h. Change ${kmh} km/h into metres per second.`, marks: 2, ans: `${N(kmh / 3.6)} m/s`, ms: [M(`for ${kmh} × 1000 ÷ 3600 or ${kmh} ÷ 3.6`), A()], line: { post: 'm/s' }, space: 2 });
  return { parts };
});

gen('r_scale', 'Ratio & Proportion', 'Scale drawings & maps', { F: [1, 2], H: [], calc: 'nocalc', spec: 'R2, G15' }, (r, band) => {
  const sc = r.pick([25000, 50000, 20000, 10000]);
  const cm1 = clean(r.int(4, 18) / 2);
  const km = cm1 * sc / 100000;
  const parts = [{ lab: '(a)', q: `A map has a scale of 1 : ${N(sc)}. On the map, the distance between two villages is ${N(cm1)} cm.<br>Work out the real distance between the villages. Give your answer in kilometres.`, marks: 2, ans: `${N(km)} km`, ms: [M(`for ${N(cm1)} × ${N(sc)} (= ${N(cm1 * sc)} cm)`), A()], line: { post: 'km' }, space: 2 }];
  if (band === 2) {
    const realKm = clean(r.int(2, 9) * sc / 100000 * r.pick([1, 2]));
    parts.push({ lab: '(b)', q: `The real distance between a school and a park is ${N(realKm)} km. How far apart are they on the map? Give your answer in centimetres.`, marks: 2, ans: `${N(realKm * 100000 / sc)} cm`, ms: [M(`for ${N(realKm)} × 100 000 ÷ ${N(sc)}`), A()], line: { post: 'cm' }, space: 2 });
    const mScale = r.pick([20, 25, 40, 50]), modelLen = r.pick([8, 10, 12, 15, 18]);
    parts.push({ lab: '(c)', q: `A model of a boat is made using a scale of 1 : ${mScale}. The model is ${modelLen} cm long. Work out the length of the real boat in metres.`, marks: 2, ans: `${N(modelLen * mScale / 100)} m`, ms: [M(`for ${modelLen} × ${mScale}`), A()], line: { post: 'm' }, space: 2 });
  }
  return { parts };
});

// ======================= Question styles from the AQA and OCR papers =======================
// Multiple choice ("Circle your answer"), "Is X correct?" decisions, "Assume… / In fact…",
// spot-the-error items, True / May be true / Not true grids, decimal search, u(n+1) sequences,
// growth formulas, "to be sure" bounds, LCM in context, kinematics formulae and area comparison.
'use strict';

const numKey = (s) => parseFloat(String(s).replace(MINUS, '-').replace(/[^\d.\-]/g, '')) || 0;

// ---------- Number: multiple choice ----------
gen('n_multiple_choice', 'Question styles', 'Multiple choice (number)', { F: [1, 2], H: [2, 3], calc: 'nocalc', spec: 'N1–N16' }, (r, band) => {
  const items = {
    1: [
      () => { const a = r.int(3, 12), b = r.int(a + 1, 18); return mcPart(r, '', `Work out ${a} + (${MINUS}${b})`, signed(a - b), [signed(-a - b), signed(b - a), signed(a + b)], numKey); },
      () => { const d = r.int(2, 9); let n; do { n = r.int(1000, 9999); } while (!String(n).includes(String(d)) || String(n).split(String(d)).length !== 2); const pos = String(n).length - 1 - String(n).indexOf(String(d)); const val = d * 10 ** pos;
        const w = [0, 1, 2, 3].filter(p => p !== pos).map(p => N(d * 10 ** p)); return mcPart(r, '', `What is the value of the digit ${d} in the number ${N(n)}?`, N(val), w, numKey); },
      () => { const pr = r.pick([23, 29, 31, 37, 41, 43, 47]); const comp = r.sample([21, 27, 33, 39, 49, 51, 57, 63], 3); return mcPart(r, '', 'Which of these numbers is a prime number?', String(pr), comp.map(String), numKey); },
      () => { const [n, d] = r.pick([[3, 5], [1, 4], [3, 4], [2, 5], [1, 8]]); const dec = N(n / d); return mcPart(r, '', `Write ${fr(n, d)} as a decimal.`, dec, [`${n}.${d}`, `0.${n}${d}`, N(clean(n / d / 10))], numKey); },
      () => { const x = clean(r.int(2, 9) / 10), k = r.pick([10, 100, 1000]); return mcPart(r, '', `Work out ${N(x)} × ${N(k)}`, N(clean(x * k)), [N(clean(x * k / 10)), N(clean(x * k * 10)), N(clean(x / k))], numKey); },
      () => { const n = r.int(121, 989); const ans = Math.round(n / 10) * 10; if (n % 10 === 5 || n % 10 === 0) return null; return mcPart(r, '', `Round ${n} to the nearest 10.`, N(ans), [N(Math.round(n / 100) * 100), N(ans === Math.floor(n / 10) * 10 ? ans + 10 : ans - 10), N(ans === Math.floor(n / 10) * 10 ? ans + 20 : ans - 20)], numKey); },
    ],
    2: [
      () => { const k = r.pick([4, 5, 8, 2]); return mcPart(r, '', `Which of these is the reciprocal of ${k}?`, N(1 / k), [signed(-k), N(k / 10), N(k / 2)], numKey); },
      () => { const b = r.pick([2, 3]), e = b === 2 ? r.int(4, 6) : r.int(3, 4); return mcPart(r, '', `Work out ${b}${sup(e)}`, N(b ** e), [N(b * e), N(e ** b), N(b + e)], numKey); },
      () => { const p = r.pick([15, 35, 45, 5]), a = r.pick([40, 60, 80, 120, 200]); const ans = p * a / 100; return mcPart(r, '', `Work out ${p}% of ${a}`, N(ans), [isInt(a / p) ? N(a / p) : N(clean(ans / 10)), N(p), N(clean(ans * 10))], numKey); },
      () => { const c = r.pick([[27, 3], [64, 4], [125, 5], [8, 2]]); return mcPart(r, '', `Work out the cube root of ${c[0]}`, N(c[1]), [N(c[0] / 3 === Math.round(c[0] / 3) ? c[0] / 3 : c[1] * 2), N(c[1] ** 2), N(c[1] * 3 === c[0] / 3 ? c[1] + 1 : c[1] * 3)], numKey); },
      () => { const m = clean(r.int(11, 98) / 10), e = r.int(3, 5); if (Number.isInteger(m)) return null; /* "6"+"00000" would duplicate the correct answer */ return mcPart(r, '', `Write ${N(m)} × 10${sup(e)} as an ordinary number.`, N(clean(m * 10 ** e)), [N(clean(m * 10 ** (e - 1))), N(clean(m * 10 ** (e + 1))), `${N(m)}${'0'.repeat(e)}`], numKey); },
      () => { let a, b; do { a = r.int(2, 6) * r.pick([2, 3]); b = r.int(2, 6) * r.pick([2, 3]); } while (a === b || gcd(a, b) === 1 || gcd(a, b) === Math.min(a, b)); return mcPart(r, '', `What is the highest common factor (HCF) of ${a} and ${b}?`, N(gcd(a, b)), [N(lcm(a, b)), N(a * b), N(gcd(a, b) === 2 ? 1 : 2)], numKey); },
    ],
    3: [
      () => { const [b, n, m] = r.pick([[8, 3, 2], [27, 3, 2], [16, 4, 3], [32, 5, 2], [64, 3, 2]]); const root = Math.round(b ** (1 / n)); return mcPart(r, '', `Work out the value of ${b}${supf(m, n)}`, N(root ** m), [N(clean(roundDp(b * m / n, 1))), N(root * m), N(b ** 2 / n === Math.round(b ** 2 / n) ? b ** 2 / n : root ** m + 1)], numKey); },
      () => { const b = r.pick([2, 3, 4, 5]), e = r.pick([2, 3].filter(x => b ** x <= 64)); return mcPart(r, '', `Work out the value of ${b}${sup(MINUS + e)}`, fr(1, b ** e), [signed(-(b ** e)), signed(-b * e), fr(1, b * e)]); },
      () => { const m = clean(r.int(11, 98) / 10), e = r.int(3, 5); const x = clean(m / 10 ** e); return mcPart(r, '', `Write ${N(x)} in standard form.`, `${N(m)} × 10${sup(MINUS + e)}`, [`${N(m)} × 10${sup(e)}`, `${N(clean(m * 10))} × 10${sup(MINUS + (e + 1))}`, `${N(m)} × 10${sup(MINUS + (e - 1))}`]); },
      () => { const k = r.pick([2, 3, 5]), s = r.pick([2, 3, 4, 5].filter(q => q !== k)); return mcPart(r, '', `Simplify √${s * s * k}`, `${s}√${k}`, [`${s * s}√${k}`, `${k}√${s * k}`, `${s * k}√${k}`]); },
      () => { const a = r.int(1, 8); const f9 = new Frac(a, 9); return mcPart(r, '', `Which fraction is equal to 0.<span class="rec">${a}</span>?`, f9.html(), [fr(a, 10), fr(a, 100), new Frac(a, 99).html()]); },
      () => { const x = clean(r.int(21, 98) / 10); return mcPart(r, '', `${v('x')} = ${N(x, 1)} correct to 1 decimal place. What is the upper bound of ${v('x')}?`, N(clean(x + 0.05)), [N(clean(x + 0.1)), N(clean(x + 0.04)), N(clean(x + 0.049))], numKey); },
    ],
  };
  const pool = items[Math.min(band, 3)];
  const picks = r.sample(pool.map((f, i) => i), 3);
  const parts = picks.map(i => pool[i]());
  if (parts.some(p => !p)) return null;
  parts.forEach((p, i) => p.lab = '(' + 'abc'[i] + ')');
  return { parts };
});

// ---------- Algebra: multiple choice ----------
gen('a_multiple_choice', 'Question styles', 'Multiple choice (algebra)', { F: [1, 2], H: [2, 3], calc: 'nocalc', spec: 'A1–A25' }, (r, band) => {
  const X = v('x'), Y = v('y'), n = v('n');
  const items = {
    1: [
      () => { const a = r.int(2, 6), x = r.int(2, 9); return mcPart(r, '', `Solve ${a}${X} = ${a * x}`, `${X} = ${x}`, [`${X} = ${a * x - a}`, `${X} = ${a * x * a}`, `${X} = ${fr(1, x)}`]); },
      () => { const a = r.int(2, 6), b = r.int(2, 6), c = r.pick(['c', 'y', 'm']); return mcPart(r, '', `Simplify ${a} × ${b}${v(c)}`, `${a * b}${v(c)}`, [`${a}${b}${v(c)}`, `${a + b}${v(c)}`, `${a * b}${v(c)}${sup(2)}`]); },
      () => { const opts = ['expression', 'equation', 'formula', 'identity']; const ex = { expression: `${r.int(2, 9)}${X} + ${r.int(1, 9)}`, equation: `${r.int(2, 9)}${X} + ${r.int(1, 9)} = ${r.int(20, 40)}`, formula: `${v('A')} = ${v('l')}${v('w')}`, identity: `2(${X} + 3) ≡ 2${X} + 6` }; const k = r.pick(opts); return mcPart(r, '', `${ex[k]}<br>Is this an expression, an equation, a formula or an identity?`, k, opts.filter(o => o !== k)); },
      () => { const a = r.int(2, 6), b = r.int(1, 9), t = r.int(5, 12); return mcPart(r, '', `The ${n}th term of a sequence is ${a}${n} + ${b}. Work out the ${ordinal(t)} term.`, N(a * t + b), [N(a * t), N(Number(`${a}${t}`) + b), N(a * (t + b))], numKey); },
    ],
    2: [
      () => { const a = r.int(2, 6), b = r.int(2, 9); return mcPart(r, '', `Expand ${a}(${X} + ${b})`, `${a}${X} + ${a * b}`, [`${a}${X} + ${b}`, `${X} + ${a * b}`, `${a}${X} + ${a + b}`]); },
      () => { const m = r.nz(-5, 5), c = r.int(1, 9); return mcPart(r, '', `What is the gradient of the line ${Y} = ${c} ${m < 0 ? MINUS : '+'} ${Math.abs(m) === 1 ? '' : Math.abs(m)}${X}?`, signed(m), [N(c), signed(-m), signed(-c)], numKey); },
      () => { const k = r.int(2, 5); return mcPart(r, '', `${X} : ${Y} = 1 : ${k}. Which equation is correct?`, `${Y} = ${k}${X}`, [`${X} = ${k}${Y}`, `${Y} = ${X} + ${k}`, `${Y} = ${fr(k, X)}`]); },
      () => { const k = r.int(2, 9); return mcPart(r, '', `Factorise ${X}${sup(2)} − ${k * k}`, `(${X} + ${k})(${X} − ${k})`, [`(${X} − ${k})${sup(2)}`, `${X}(${X} − ${k * k})`, `(${X} + ${k * k})(${X} − 1)`]); },
      () => { const d = r.int(2, 5), x = r.int(2, 9); return mcPart(r, '', `Solve ${fr(X, d)} = ${x}`, `${X} = ${d * x}`, [`${X} = ${new Frac(x, d).html()}`, `${X} = ${x + d}`, `${X} = ${signed(x - d)}`]); },
    ],
    3: [
      () => { const k = r.int(2, 9); return mcPart(r, '', `Solve ${X}${sup(2)} = ${k}${X}`, `${X} = 0 or ${X} = ${k}`, [`${X} = ${k} only`, `${X} = ${MINUS}${k} or ${X} = ${k}`, `${X} = 0 or ${X} = ${MINUS}${k}`]); },
      () => { const a = r.int(2, 6); return mcPart(r, '', `Expand (${X} + ${a})${sup(2)}`, quad(1, 2 * a, a * a), [quad(1, 0, a * a), quad(1, a, a * a), quad(1, 2 * a, 2 * a)]); },
      () => { const a = r.int(2, 5), b = r.int(1, 9), c = r.int(1, 6); const rhs = a * c + b; return mcPart(r, '', `Solve ${a}${X} + ${b} > ${rhs}`, `${X} > ${c}`, [`${X} < ${c}`, `${X} > ${new Frac(rhs + b, a).html()}`, `${X} = ${c}`]); },
      () => mcPart(r, '', `${Y} is inversely proportional to ${X}. Which of these could be the equation connecting ${X} and ${Y}?`, `${Y} = ${fr(r.pick([6, 8, 12, 20]), X)}`, [`${Y} = ${r.pick([3, 4, 5])}${X}`, `${Y} = ${X} ${MINUS} ${r.pick([2, 3, 4])}`, `${Y} = ${X}${sup(2)}`]),
      () => { const g = r.int(2, 5), [x0, y0] = [r.int(1, 4), r.int(1, 9)]; const c = y0 - g * x0; return mcPart(r, '', `A line has gradient ${g} and passes through (${x0}, ${y0}). What is the equation of the line?`, `${Y} = ${lin(g, c)}`, [`${Y} = ${lin(g, y0)}`, `${Y} = ${lin(x0, c)}`, `${Y} = ${lin(g, y0 + g * x0)}`]); },
    ],
  };
  const pool = items[Math.min(band, 3)];
  const parts = r.sample(pool.map((f, i) => i), 3).map(i => pool[i]());
  if (parts.some(p => !p)) return null;
  parts.forEach((p, i) => p.lab = '(' + 'abc'[i] + ')');
  return { parts };
});

// ---------- Ratio & proportion: "Is X correct? Show how you decide" and "Assume… / In fact…" ----------
gen('r_decide', 'Question styles', 'Is it correct? Decide and explain', { F: [1, 2], H: [2], calc: 'either', spec: 'R9, R10, N2' }, (r, band, ctx) => {
  const name = r.pick(NAMES), other = r.pick(NAMES.filter(x => x !== name));
  const kind = band === 1 ? r.pick(['assume', 'pctless']) : r.pick(['percent', 'rate', 'assume', 'pctless']);
  if (kind === 'assume') {
    // AQA "Assume the offer is permanent… In fact…"
    const C_ = r.pick([18, 20, 24, 25, 30, 36]), s = r.pick([4, 5, 6, 8]);
    const cost = C_ * 1.5, nOffer = Math.ceil(cost / s - 1e-9), nFull = Math.ceil(2 * C_ / s - 1e-9);
    if (nFull <= nOffer || !isInt(cost)) return null;
    const item = r.pick(['concert tickets', 'video games', 'pairs of trainers', 'board games']);
    const one = { 'concert tickets': 'ticket', 'video games': 'game', 'pairs of trainers': 'pair', 'board games': 'game' }[item];
    return { stem: `${cap(item)} cost £${C_} each.<br>Offer: buy one ${one} and get a second ${one} for half price.<br>${name} wants to buy two ${item}. ${cap(pron(name))} saves £${s} every Saturday.`, parts: [
      { lab: '(a)', q: `Assume the offer is permanent. How many Saturdays does ${name} need to save for? You must show your working.`, marks: 3, ans: `${nOffer} Saturdays (£${C_} + £${N(C_ / 2)} = £${N(cost)}, and ${N(cost)} ÷ ${s} = ${N(roundDp(cost / s, 2))}${isInt(cost / s) ? '' : ', rounded up'})`, ms: [M(`for £${C_} + £${N(C_ / 2)} (= £${N(cost)})`), M(`for ${N(cost)} ÷ ${s} (= ${N(roundDp(cost / s, 2))}) or repeated adding of ${s}`), A(`for ${nOffer}`)], line: { post: 'Saturdays' }, space: 3 },
      { lab: '(b)', q: `In fact, the offer only lasts for 1 week. No new offers are planned.<br>What does this mean about the number of Saturdays ${name} needs to save for? Tick one box.${tickList(['It is less than the answer to part (a)', 'It is the same as the answer to part (a)', 'It is greater than the answer to part (a)', 'It is not possible to tell'])}`, marks: 1, ans: `It is greater than the answer to part (a) (two ${item} at full price cost £${2 * C_}, which needs ${nFull} Saturdays).`, ms: [B('for “It is greater than the answer to part (a)”')], line: null, space: 0.2 }] };
  }
  if (kind === 'pctless') {
    // OCR: "Riley says she spent 50% less time… Is she correct?"
    const a = r.pick([24, 30, 36, 40, 48, 60]), claim = r.pick([25, 50, 20, 40]);
    const trueP = r.chance(0.5) ? claim : r.pick([claim / 2, claim + 10, claim + 20].filter(x => x !== claim && x > 0 && x < 70));
    const b = clean(a * (100 - trueP) / 100);
    if (!isInt(b)) return null;
    const ok = trueP === claim;
    const months = r.pick([['March', 'April'], ['January', 'February'], ['May', 'June']]);
    return { stem: `${name} goes to the gym. ${cap(pron(name))} spent ${a} hours at the gym in ${months[0]} and ${b} hours at the gym in ${months[1]}.`, parts: [
      { lab: '', q: `${name} says, “I spent ${claim}% less time at the gym in ${months[1]} than in ${months[0]}.”<br>Is ${name} correct? Show how you decide.`, marks: 2, ans: `${ok ? 'Yes' : 'No'}: ${a} − ${b} = ${a - b} hours less, and ${a - b} ÷ ${a} × 100 = ${N(trueP)}%${ok ? '' : `, not ${claim}%`}.`, ms: [M(`for (${a} − ${b}) ÷ ${a} × 100 or ${a} × ${N(1 - claim / 100)} (= ${N(clean(a * (1 - claim / 100)))})`), C(`for ${ok ? 'Yes' : 'No'} with ${N(trueP)}% (or ${N(clean(a * (1 - claim / 100)))} hours) as evidence`)], line: null, space: 2.5 }] };
  }
  if (kind === 'percent') {
    // AQA: Ellie paid 10% less for one item and 20% more for another
    let A1, B1, p1, p2;
    for (let t = 0; t < 200; t++) { A1 = r.pick([80, 120, 150, 160, 200, 240]); B1 = r.pick([20, 25, 30, 40, 50, 60]); p1 = r.pick([10, 15, 20, 25]); p2 = r.pick([20, 25, 30, 40, 50].filter(x => x > p1)); if (A1 * p1 / 100 !== B1 * p2 / 100 && isInt(A1 * p1 / 100) && isInt(B1 * p2 / 100)) break; }
    const d1 = A1 * p1 / 100, d2 = B1 * p2 / 100, tot1 = A1 + B1, tot2 = A1 - d1 + B1 + d2;
    const yes = tot2 > tot1;
    const [it1, it2] = r.pick([['a printer', 'a hard drive'], ['a bike', 'a helmet'], ['a coat', 'a scarf'], ['a tablet', 'a case']]);
    return { stem: `${other} paid £${A1} for ${it1} and £${B1} for ${it2}.<br>${name} paid ${p1}% less than ${other} for ${it1}. ${cap(pron(name))} paid ${p2}% more than ${other} for ${it2}.`, parts: [
      { lab: '', q: `${name} says, “I paid more than ${other} in total, because ${p2}% is greater than ${p1}%.”<br>Is ${name} correct? Tick a box.${yesNo()}Show calculations to support your answer.`, marks: 3, ans: `${yes ? 'Yes' : 'No'}. ${other} paid £${tot1}. ${name} paid £${A1 - d1} + £${B1 + d2} = £${tot2}${yes ? ', which is more' : ', which is less'}. (${name} saved £${d1} but paid £${d2} extra.)`, ms: [M(`for ${p1}% of ${A1} (= ${d1}) or ${p2}% of ${B1} (= ${d2})`), M(`for both totals (£${tot1} and £${tot2}) or comparing £${d1} with £${d2}`), C(`for ${yes ? 'Yes' : 'No'} with correct supporting figures`)], line: null, space: 3 }] };
  }
  // rate: OCR "Can she complete the order in 3 days?"
  let c, m, Nn, h, d, need, have, found = false;
  for (let t = 0; t < 600 && !found; t++) { c = r.int(2, 5); m = r.pick([20, 24, 30, 36, 40, 45, 48]); Nn = r.pick([60, 80, 90, 100, 120, 150]); h = r.pick([6, 7, 8]); d = r.int(2, 4); need = Nn / c * m; have = d * h * 60; // every printed intermediate value must be exact (no recurring decimals)
    if (Nn % c === 0 && (m * 100) % c === 0 && need % 15 === 0 && Math.abs(need - have) >= 30) found = true; }
  if (!found) return null;
  const can = need <= have;
  return { stem: `${name} makes greetings cards. ${cap(pron(name))} makes ${c} cards in ${m} minutes. ${cap(pron(name))} has an order for ${Nn} cards. ${cap(pron(name))} works for ${h} hours each day.`, parts: [
    { lab: '(a)', q: `Can ${name} complete the order in ${d} days? Show how you decide.`, marks: 4, ans: `${can ? 'Yes' : 'No'}: ${Nn} ÷ ${c} × ${m} = ${N(need)} minutes needed (${N(clean(need / 60))} hours); ${d} × ${h} = ${d * h} hours (${N(have)} minutes) available.`, ms: [M(`for ${Nn} ÷ ${c} (= ${N(Nn / c)}) or ${m} ÷ ${c} (= ${N(clean(m / c))} minutes per card)`), M(`for ${N(Nn / c)} × ${m} or ${N(clean(m / c))} × ${Nn} (= ${N(need)} minutes)`), M(`for ${d} × ${h} × 60 (= ${N(have)}) or converting to the same units`), C(`for ${can ? 'Yes' : 'No'} with correct comparison of ${N(need)} and ${N(have)} minutes (or hours)`)], line: null, space: 4 },
    { lab: '(b)', q: `Write down one assumption you have made.`, marks: 1, ans: `${name} works at the same rate all the time (or takes no breaks).`, ms: [C('for a sensible assumption, e.g. works at a constant rate')], line: null, space: 1 }], calc: ctx.calc ? 'calc' : undefined };
});

// ---------- Algebra: spot the error ----------
gen('a_errors', 'Question styles', 'Spot the mistake (algebra)', { F: [2], H: [2, 3], calc: 'nocalc', spec: 'A1–A18' }, (r, band) => {
  const X = v('x'), Y = v('y'), a = v('a'), b = v('b');
  const nm = () => r.pick(NAMES);
  const box = (lines) => `<div class="workbox">${lines.join('<br>')}</div>`;
  const items = [
    () => { const k = r.int(2, 5), p = r.int(2, 4), q = r.int(2, 4); const who = nm();
      return { q: `${who} simplifies ${k}(${a} + ${p}${b}) + ${q}${a}${box([`= ${k}${a} + ${p}${b} + ${q}${a}`, `= ${k + q}${a} + ${p}${b}`])}Describe the mistake ${who} made and give the correct answer.`, marks: 2,
        ans: `${who} did not multiply ${p}${b} by ${k}. Correct answer: ${k + q}${a} + ${k * p}${b}`, ms: [B(`for the brackets not fully expanded (${p}${b} should be multiplied by ${k})`), B(`for ${k + q}${a} + ${k * p}${b}`)] }; },
    () => { const k = r.int(2, 4); const who = nm();
      return { q: `${who} writes ${k}${a} × ${a} × ${a} = ${k + 2}${a}<br>Describe the mistake and give the correct answer.`, marks: 2, ans: `${who} added instead of multiplying the ${a}’s. Correct answer: ${k}${a}${sup(3)}`, ms: [B(`for ${a} × ${a} × ${a} is ${a}${sup(3)}, not 3${a} (or added instead of multiplied)`), B(`for ${k}${a}${sup(3)}`)] }; },
    () => { const k = r.int(2, 7); const who = nm();
      return { q: `${who} says, “(${X} + ${k})${sup(2)} = ${X}${sup(2)} + ${k * k}”<br>Explain why ${who} is wrong and write the correct expansion.`, marks: 2, ans: `(${X} + ${k})${sup(2)} = (${X} + ${k})(${X} + ${k}) = ${quad(1, 2 * k, k * k)}. ${who} has left out the ${2 * k}${X} term.`, ms: [B(`for a correct reason, e.g. it is (${X} + ${k})(${X} + ${k}), so there are two ${k}${X} terms`), B(`for ${quad(1, 2 * k, k * k)}`)] }; },
    () => { const m = r.int(2, 6), c = r.int(3, 20); const who = nm();
      return { q: `${who} makes ${X} the subject of ${Y} = ${m}${X} + ${c}${box([`${X} = ${fr(Y, m)} − ${c}`])}Describe the mistake and give the correct answer.`, marks: 2, ans: `${who} divided by ${m} before subtracting ${c} (only ${Y} was divided by ${m}). Correct: ${X} = ${fr(`${Y} − ${c}`, m)}`, ms: [B(`for ${c} should be subtracted first (or ${c} must also be divided by ${m})`), B(`for ${X} = ${fr(`${Y} − ${c}`, m)} oe`)] }; },
    () => { const p = r.int(2, 6), q = p * r.int(2, 6) + r.int(1, 9); const ans = (q - r.int(0, 0)); const s = r.int(2, 9), lhs = p, rhs = q; const xx = new Frac(rhs - s, lhs); if (xx.d !== 1) return null; const who = nm();
      return { q: `${who} solves ${p}${X} + ${s} = ${rhs}${box([`${p}${X} = ${rhs + s}`, `${X} = ${new Frac(rhs + s, p).html()}`])}Describe the mistake and give the correct answer.`, marks: 2, ans: `${who} added ${s} to ${rhs} instead of subtracting it. ${p}${X} = ${signed(rhs - s)}, so ${X} = ${signed(xx.n)}`, ms: [B(`for should subtract ${s} (not add)`), B(`for ${X} = ${signed(xx.n)}`)] }; },
    () => { const m = r.int(2, 6), n2 = r.int(2, 6); if (m + n2 === m * n2) return null; const who = nm();
      return { q: `${who} writes ${X}${sup(m)} × ${X}${sup(n2)} = ${X}${sup(m * n2)}<br>Describe the mistake and give the correct answer.`, marks: 2, ans: `${who} multiplied the powers instead of adding them. Correct answer: ${X}${sup(m + n2)}`, ms: [B('for the powers should be added, not multiplied'), B(`for ${X}${sup(m + n2)}`)] }; },
  ];
  const hard = [
    () => { const p = r.int(2, 5), q = r.int(2, 5), s = r.int(1, 5), t = r.int(1, 6); if (p === q) return null; const who = nm();
      return { q: `${who} starts to simplify ${fr(p, `${X} − ${s}`)} + ${fr(q, `${X} + ${t}`)}<br>Here is the first line of ${who}’s working.${box([`= ${fr(`${p}(${X} − ${s}) + ${q}(${X} + ${t})`, `(${X} − ${s})(${X} + ${t})`)}`])}Describe the error. You do not need to complete the simplification.`, marks: 1, ans: `Each numerator has been multiplied by its own denominator. It should be ${p}(${X} + ${t}) + ${q}(${X} − ${s}).`, ms: [B(`for the numerator should be ${p}(${X} + ${t}) + ${q}(${X} − ${s}) oe`)] }; },
    () => { const k = r.int(2, 9); const who = nm();
      return { q: `${who} solves ${X}${sup(2)} = ${k}${X}${box([`${X} = ${k}`])}Explain why ${who}’s answer is not complete.`, marks: 1, ans: `${who} divided both sides by ${X}, which loses the solution ${X} = 0. The solutions are ${X} = 0 and ${X} = ${k}.`, ms: [B(`for ${X} = 0 is also a solution (dividing by ${X} loses it)`)] }; },
    () => { const [p, q] = r.pick([[3, 4], [4, 3], [5, 12], [12, 5], [6, 8], [8, 6]]); const who = nm();
      return { q: `${who} says, “√(${X}${sup(2)} + ${q * q}) = ${X} + ${q}”<br>Show that ${who} is wrong.`, marks: 1, ans: `For example, when ${X} = ${p}: √(${p * p} + ${q * q}) = √${p * p + q * q} = ${Math.sqrt(p * p + q * q)}, but ${p} + ${q} = ${p + q}.`, ms: [C('for a correct counter-example with both values worked out')] }; },
  ];
  const pool = band >= 3 ? hard.concat(items.slice(2, 4)) : items;
  const [i1, i2] = r.sample(pool.map((f, i) => i), 2);
  const p1 = pool[i1](), p2 = pool[i2]();
  if (!p1 || !p2) return null;
  const parts = [p1, p2].map((p, i) => ({ lab: '(' + 'ab'[i] + ')', q: p.q, marks: p.marks, ans: p.ans, ms: p.ms, line: null, space: 1.5 }));
  return { parts };
});

// ---------- Statistics: True / May be true / Not true, and misconceptions ----------
gen('s_judge', 'Statistics', 'Interpreting & criticising statistics', { F: [2], H: [2, 3], calc: 'nocalc', spec: 'S1, S4' }, (r, band) => {
  let m1, m2, r1, r2; do { m1 = r.int(45, 75); m2 = r.int(45, 75); r1 = r.int(10, 30); r2 = r.int(10, 30); } while (Math.abs(m1 - m2) < 3 || Math.abs(r1 - r2) < 3);
  const [gA, gB] = r.pick([['School A', 'School B'], ['Class 10X', 'Class 10Y'], ['Team Red', 'Team Blue']]);
  const what = gA.startsWith('Team') ? 'scores' : 'test marks';
  const sts = [
    [`On average, ${gA} had higher ${what}.`, m1 > m2 ? 'True' : 'Not true'],
    [`${gB}’s ${what} were more spread out.`, r2 > r1 ? 'True' : 'Not true'],
    [`There were more students in ${gB} than in ${gA}.`.replace('students', gA.startsWith('Team') ? 'players' : 'students'), 'May be true'],
    [`The highest mark was scored in ${gA}.`.replace('mark', gA.startsWith('Team') ? 'score' : 'mark'), 'May be true'],
  ];
  const use = r.shuffle(r.sample(sts.slice(0, 2), 2).concat(r.sample(sts.slice(2), 1)));
  const parts = [{ lab: '(a)', q: `Tick one box for each statement.${tickGrid(['True', 'May be true', 'Not true'], use.map(s => s[0]))}`, marks: 3, ans: use.map(s => `${s[0]} <b>${s[1]}</b>`).join('<br>'), ms: use.map(s => B(`for ${s[1]} (${s[0].replace(/\.$/, '')})`)), line: null, space: 0.3 }];
  // median misconception
  let d; do { d = Array.from({ length: 7 }, () => r.int(10, 45)); } while (new Set(d).size < 7 || d[3] === d.slice().sort((x, y) => x - y)[3]);
  const sorted = d.slice().sort((x, y) => x - y), who = r.pick(NAMES);
  parts.push({ lab: '(b)', q: `Here are seven numbers.<div class="numlist">${d.join('&emsp;')}</div>${who} says, “The median is ${d[3]} because it is the middle number.”<br>Explain why ${who} is not correct, and work out the median.`, marks: 2, ans: `The numbers need to be put in order first: ${sorted.join(', ')}. The median is ${sorted[3]}.`, ms: [B('for the numbers need to be in order first'), B(`for ${sorted[3]}`)], line: null, space: 2 });
  if (band >= 3) {
    const ctxS = r.pick([['a town council', 'how people travel to work', 'outside the railway station', 20], ['a leisure centre', 'how often people exercise', 'inside the gym', 25], ['a school', 'what students think of school lunches', 'in the dinner queue on one Monday', 15]]);
    parts.push({ lab: '(c)', q: `${cap(ctxS[0])} wants to find out ${ctxS[1]}. Their interviewer stands ${ctxS[2]} and asks ${ctxS[3]} people.<br>Give two criticisms of this sampling method.`, marks: 2, ans: `The sample is biased: only people ${ctxS[2]} were asked, so they are not representative of everyone; ${ctxS[3]} people is a small sample; it is only at one place/time.`, ms: [B('for one valid criticism, e.g. biased location'), B('for a second different valid criticism, e.g. sample too small or only one time/day')], line: null, space: 2 });
  }
  return { stem: `The table shows information about the ${what} of ${gA} and ${gB}.`, fig: table([['', 'Mean', 'Range'], [gA, m1, r1], [gB, m2, r2]], { rowHead: true }), parts };
});

