  const m5 = nums.filter(x => x % 5 === 0), ev = nums.filter(x => x % 2 === 0), both = nums.filter(x => x % 10 === 0), either = nums.filter(x => x % 5 === 0 || x % 2 === 0);
  const flips = r.int(6, 9), tot = 10;
